/* TYT matematik 121–240: kaynak şekilleri üzerinden bireysel analizler. */
(function(){
const rows={};
function M(n,title,topic,page,tests,knowledge,reasoning,trap,concept,why,stem,options,answer,explanation){rows[`q-tyt-matematik-${String(n).padStart(3,'0')}`]={title,topic,lessonIds:[],studyRefs:[{book:'TYT-mat',page,title:topic}],tests,knowledge,reasoning,trap,connections:[{concept,why}],variation:{stem,options,answer,explanation},status:'reviewed',keyCheck:'matches',note:''};}
M(121,'Yağ oranından yumurta sayısına','Karışım problemleri',53,'Argan ve zeytinyağı miktarlarının toplam karışıma değil bademyağına oranlandığını kullanarak iki tarifin toplam yağ hacmini buldurur.',['Her şişe 60 mL; argan bademin%40’ı, zeytinyağı bademin%75 idir.','Her 70 mL toplam yağ karışımı için 1 yumurta gerekir.'],['Deniz 60 mL argan için 60/0,4 = 150 mL badem kullanır; toplam 210 mL ve 3 yumurta.','Eylül 120 mL zeytin için 120/0,75 = 160 mL badem; toplam 280 mL ve 4 yumurta. Toplam 7, D.'],'Yüzdeleri toplam karışımın yüzdesi sanmak; referans bademyağıdır, toplam hacim ayrıca hesaplanır.','Referans oran','Aynı yüzde farklı tabana uygulandığında başka hacim verir; tarifteki kimin yüzde kaçı ilişkisi önce okunmalıdır.','Bademin yarısı kadar 90 mL başka yağ ekleniyor. Toplam karışım kaç mL?',['180','210','240','270','300'],3,'90 mL bademin yarısıysa badem 180 mL; toplam 270 mL.');
M(122,'İki kasa türünde aynı ürün toplamı','Yüzde problemleri',51,'Ahşap ve plastik kasaların ayrı denemelerde aynı toplam domatesin farklı yüzdelerini taşıdığını karşılaştırır.',['30 ahşap kasanın toplamı 30 × 8 = 240 kg dır.','Bu 240 kg toplam ürünün%60’ı olduğundan toplam 400 kg dır.'],['Plastik kasalara konan miktar 400 × 0,65 = 260 kg.','20 özdeş plastik kasanın biri 260/20 = 13 kg taşır; E. İki deneydeki yüzdeler birbiriyle toplanmaz.'],'%60 ile%65’i iki ayrı ürün toplamı gibi kullanmak veya 260 ı30 kasaya bölmek.','Oran zinciri','Önce ortak toplam bulunur, sonra ikinci yüzdeye geçilir; 240·65/60/20 doğrudan işlemle de aynı sonucu verir.','10 kasa toplam ürünün%40 ını taşıyor; her biri 6 kg. Toplam ürün kaç kg?',['100','120','150','180','240'],2,'60 kg toplamın 0,4 üdür; 60/0,4 = 150 kg.');
M(123,'Asansörde en ağır üç, en hafif dört','Eşitsizlikler',32,'Hangi üç kişinin binse uyarı vermemesi ve hangi dört kişinin binse vermesi koşullarını uç alt kümelerle sınırlar.',['En ağır üç kişinin toplamı 50 + 60 + 63 = 173 kg.','En hafif dört kişinin toplamı 25 + 40 + 50 + 60 = 175 kg dır.'],['Kapasite en az 173 olmalı ki bütün üçlüler taşınsın.','Uyarı yalnız kapasite aşılınca geldiğinden kapasite 175’ten küçük olmalı. 173 ≤ K < 175 aralığında seçenek 174; C.'],'Tüm beş kişinin toplamını kapasite sanmak veya en ağır dörtle üst sınır kurmak; bütün dörtlüler koşulu en hafifle sınanır.','En kötü durum','Evrensel koşullar uygun uç örnekle denetlenir; bir eşik bütün alt kümeleri aynı anda kapsar.','En ağır üç toplam 160, en hafif dört 170. Hangi kapasite iki koşulu sağlar?',['155','159','165','170','180'],2,'160 ≤ K < 170 aralığı gerekir; 165 uygundur.');
M(124,'Eşit çarpımdan sonra eşit toplam','Sayı problemleri',47,'Terazide toplam eşitliğini, ayrı verilen çarpım eşitliğinden ayırır; 1 kg lar çarpımı değiştirmeden toplamı düzeltir.',['3·4·5·6·10 = 3600 olduğundan her kefenin büyük ağırlık çarpımı 60 olmalıdır.','1 kg ağırlık çarpımı değiştirmez fakat bulunduğu kefenin toplamına 1 ekler.'],['60 çarpımı 3·4·5 ve 6·10 gruplarıyla elde edilir. Toplamlar 12 ve 16 kg.','Hafif kefeye dört 1 kg eklenince toplamlar eşitlenir; minimum 4, D. Ek 1 kg lar iki kefeye dağılırsa gereken toplam artar.'],'Çarpımlar eşit diye terazinin zaten dengede olduğunu sanmak; terazi kütle toplamını karşılaştırır.','Çarpım ve toplam kısıtı','Aynı sayı grubunda iki farklı işlemle verilen koşullar bağımsızdır; 1 çarpmanın etkisiz elemanı olduğu için ayarlama aracı olur.','Çarpımları eşit iki kefenin toplamları 18 ve 23 kg. 1 kg larla en az kaç ek gerekir?',['3','4','5','6','7'],2,'Hafif kefeye 5 kg eklemek farkı kapatır; daha azı yetmez.');
M(125,'Kutunun dışında kalan desen parçaları','Periyodik problemler',25,'Altı taşlık 3 sarı 2 mavi 1 kırmızı desenin toplam rengini, şekilde görünen dış parçaları çıkararak iç koşulla eşitler.',['Tam bileklik k tekrar ise sarı 3k, mavi 2k, kırmızı k dır.','Şekilde dışarıda 9 sarı ve 4 mavi bulunur; iki uç birlikte sayılmalıdır.'],['İç sarı 3k − 9, iç mavi 2k − 4. Koşul 3k − 9 = (2k − 4) + 2.','Buradan k = 7; toplam 6k = 42 taş, C. Dışarıdaki kırmızılar sarı–mavi fark denklemine girmez.'],'Yalnız kutunun tek yanındaki taşları saymak veya iç sarının tüm mavilerden iki fazla olduğunu yazmak.','Bütün eksi görünen','Gizlenen iç miktarlar toplam desenle görünen uçlar arasındaki farktır; renk koşulu tekrar sayısını belirler.','Desende 3 kırmızı 2 beyaz var. 5 tekrarın dışında 4 kırmızı 3 beyaz görülüyor. İçte kaç kırmızı vardır?',['8','9','10','11','12'],3,'Toplam kırmızı 15; görünen 4 çıkarılınca 11 kalır.');
M(126,'İki varış saatinden ortak mesafe','Hareket problemleri',54,'Aynı kalkışla 100 ve 60 km/h hızlarda varışların iki saat farkından yolu, sonra 10.00 hedefi için hızı buldurur.',['Yol aynı olduğundan süreler D/100 ve D/60’tır.','11.00 ile 09.00 arasındaki 2 saat süre farkıdır.'],['D/60 − D/100 = 2; D/150 = 2 ve D = 300 km. 100 hızla 3 saat gittiğine göre kalkış 06.00.','10.00’a kadar 4 saat var; 300/4 = 75 km/h, B. Hızların aritmetik ortalaması 80 doğru değildir.'],'Varış saati ortada diye hızları ortalamak; sabit yol için süreyle hız ters orantılıdır.','Ortak yol modeli','Kalkış saati bilinmese de sürelerin farkı onu yok eder; mesafeden sonra saat geri bulunur.','240 km yola 06.00’da çıkan araç 10.00’da varmak için kaç km/h gitmeli?',['40','50','60','70','80'],2,'Dört saat için 240/4 = 60 km/h.');
M(127,'Ayraçla ölçülen karton','Oran orantı',46,'Aynı karton uzunluğunun ayraç uzun kenarının 10, kısa kenarının 25 katı oluşundan ayraç oranını çıkarır.',['Ayraç kısa s, uzun l ise 10l = 25s; l = 2,5s.','Karton kısa kenarı 15s, uzun kenarı 25s tir.'],['Çevre 320 olduğundan 2(25s + 15s) = 320; s = 4 cm.','Ayraç uzun 10 cm, kısa 4 cm; çevre 2(10 + 4) = 28 cm, C. 320 ayraç çevresi değil karton çevresidir.'],'10 ve 25 kat bilgilerini iki farklı karton kenarına bağlamak; ikisi de kartonun uzun kenarını ölçer.','Ortak referans','Bir uzunluğun iki farklı ölçü birimiyle ifadesi bu birimlerin oranını belirler; sonra çevre gerçek ölçeği verir.','Dikdörtgenin uzun kenarı kısa kenarın 2,5 katı, kısası 6 cm. Çevre kaç cm?',['30','36','40','42','48'],3,'Uzun 15 cm; çevre 2(15 + 6) = 42 cm.');
M(128,'Hiç, bir, iki A içeren kelimeler','Denklem sistemi',33,'80 kelimenin içerme oranından A içeren kelime sayısını bulup harf toplamını kelime toplamından ayırır.',['A içermeyen n ise içeren 3n; 4n = 80.','Bir A lı x, iki A lı y kelime için kelime sayısıx + y, harf sayısıx + 2y dir.'],['A içeren 60, içermeyen 20 kelime vardır.','x + y = 60, x + 2y = 105; çıkarma y = 45, x = 15 verir. Yalnız bir A içeren 15 kelime, B.'],'105 harfi 105 kelime saymak veya üç kat ilişkisini toplam 80’e doğrudan uygulamak.','İki farklı sayım','Aynı nesneler bir kez kelime, diğerinde harf katkısı olarak sayılır; iki denklem çift katkılı kelimeleri belirler.','40 kelimenin her biri 1 veya 2 A içeriyor, toplam 65 A var. Tek A lı kaç kelime?',['10','15','20','25','30'],1,'x + y40, x + 2y65; y25, x15.');
M(129,'Eşit çikolatada parça sayısı','Sayı problemleri',47,'Gram toplamını kişi başı hedefe bölüp her kardeşin vereceği ağırlığı paketlerin gerçek boylarıyla tamamlar.',['Fatma 135, Uğur 120 gram; toplam 255 gram üçe bölününce 85 gramdır.','Fatma 50, Uğur 35 gram vermelidir; çikolatalar bölünmeden aktarılır.'],['Fatma 50’yi 30 + 10 + 10 ile üç çikolatada verir.','Uğur 35 i15 + 10 + 10 ile üç çikolatada verir. Başlangıçta çikolatasız Nilay 6 çikolata alır; B. Eşitlik parça değil ağırlık içindir.'],'Üç kardeşe eşit çikolata adedi gerektiğini varsaymak; 10,15,30 gramlık parçalar farklıdır.','Ayrık miktar bileşimi','Hedef ağırlık paket boylarının tamsayı toplamıyla karşılanır; şekildeki stoklar hangi bileşimin mümkün olduğunu sınırlar.','30,10,10 gramlık üç çikolatanın toplamı 50 gram. Bu üçü verilen kişinin kaç parçası olur?',['2','3','4','5','6'],1,'Üç ayrı çikolata 50 gram eder; parça sayısı 3’tür.');
M(130,'Ses simgelerinin ortak başlangıç aralığı','Eşitsizlikler',32,'17 artışla yüksek simgeye,18 azalışla düşük simgeye geçen başlangıç değerini iki kapalı aralıkta sınırlar.',['Yüksek simge 66–100, düşük simge 1–32 birimdir.','Başlangıç s için 66 ≤ s + 17 ≤ 100 ve 1 ≤ s − 18 ≤ 32 yazılır.'],['Birinci 49 ≤ s ≤ 83, ikinci 19 ≤ s ≤ 50 verir.','Kesişim 49 ≤ s ≤ 50; tam sayılar 49 ve 50, toplam 99, E. Simge değişimi tek bir başlangıç değeri vermek zorunda değildir.'],'Düşük simgenin 0’ı kapsadığını varsaymak veya 17 ile 18’i doğrudan başlangıçtan bağımsız toplamak.','Ters aralık dönüşümü','İşlem sonrası aralıklar işlem tersine uygulanarak başlangıca taşınır; sonra ortak değerler seçilir.','s + 10 en az 40, s − 5 en fazla 27 ve s tam sayı. Olası s toplamı kaçtır?',['60','63','90','93','96'],3,'30 ≤ s ≤ 32; 30 + 31 + 32 = 93.');
M(131,'Hesaptaki tatlının payı','Kesir problemleri',48,'Eksik tatlı bedelini toplamdan içecekleri çıkararak bulur; ek çaylarla büyüyen yeni hesabın 2/7 sini bu sabit bedele eşitler.',['Beş çay 7,5 TL, portakal 9 TL; tatlı 28,5 − 16,5 = 12 TL dir.','Ek çay tatlı bedelini değiştirmez, yalnız toplam hesabı artırır.'],['Yeni toplam T için(2/7)T = 12; T = 42 TL.','Ek bedel 42 − 28,5 = 13,5 TL; çay 1,5 TL olduğundan 9 bardak, C. İlk beş çay ek sayıya dahil değildir.'],'Tatlıyı 28,5’in 2/7 si sanmak; oran gelecekteki yeni toplam için istenir.','Sabit parça, değişen bütün','Aynı 12 TL lik parça bütün büyüdükçe daha küçük oran oluşturur; istenen oran yeni bütünü belirler.','Tatlı 10 TL, yeni hesabın 1/4’ü olacak. Başlangıç 25 TL ise kaç TL daha harcanmalı?',['10','12','15','20','25'],2,'Yeni toplam 40 TL; 40 − 25 = 15 TL eklenir.');
M(132,'İki kalemde iki farklı kampanya','Yüzde problemleri',51,'İkinci ürüne%50 indirimle toplam 1,5 etiket fiyatını, her ürüne%30 indirimle toplam 1,4 etiket fiyatından ayırır.',['Kırmızı ikili p + 0,5p = 1,5p tutar.','Mavi ikili 2·0,7p = 1,4p tutar; etiket fiyatları aynıdır.'],['Kırmızı–mavi bedel farkı 0,1p dir.','0,1p = 4,5 TL olduğundan p = 45 TL, A. Kampanya yüzdelerinin doğrudan farkı%20 toplam ödeme farkını vermez.'],'İkinciye%50 indirimi iki ürüne birden uygulamak veya%30 indirimi yalnız ikinci maviye yapmak.','Ağırlıklı indirim','İndirim hangi ürünlere uygulanıyorsa toplam katsayı o kapsamla hesaplanır; aynı yüzde farklı kapsamda başka toplam verir.','İki ürün etiketi 20 TL. İkinci yarı fiyat kampanyasında toplam ödeme kaç TL?',['20','25','30','35','40'],2,'İlk 20, ikinci 10 TL; toplam 30.');
M(133,'Karşılaşmadan sonraki sürelerin geometrik ortalaması','Hareket problemleri',54,'Karşılıklı yolculukta karşılaşma öncesi alınan parçaların diğer araç tarafından kalan sürede alınmasını iki eşitlikle ilişkilendirir.',['İlk hız u, ikinci v, karşılaşma süresi t olsun.','ut = v·160 ve vt = u·250; karşılaşma noktası iki aracın kalan yollarını çapraz eşler.'],['İki eşitlik çarpılınca uv·t² = uv·160·250.','Hızlar sadeleşir; t² = 40000, t = 200 dakika, D. 250 ve 160’ın aritmetik ortalaması 205 uygun değildir.'],'Karşılaşma sonrası iki süreyi doğrudan toplamak veya başlangıç hızlarını eşit varsaymak.','Çapraz yol ilişkisi','Her aracın önce aldığı mesafe diğerinin sonra aldığıdır; bu simetri bilinmeyen hızları çarparak yok eder.','Karşılaşma sonrası süreler 90 ve 160 dakika ise karşılaşma öncesi süre kaçtır?',['100','110','120','125','130'],2,'t = √(90·160) = √14400 = 120 dakika.');
M(134,'Menü değiştirenlerde net artış','Denklem sistemi',33,'On kişinin iki zıt yönde menü değiştirmesini,+20 ve − 20 TL etkilerle toplam 80 TL farkına dönüştürür.',['Sebzeden ete geçiş 20 TL artırır; etten sebzeye geçiş 20 TL azaltır.','İki yöndeki kişi sayıları toplam 10’dur.'],['Ete geçen x ise sebzeye geçen 10 − x. Net artış 20x − 20(10 − x) = 80.','40x − 200 = 80; x = 7, C. Toplam 10 kişinin hepsi daha pahalı menüye geçmemiştir.'],'80/20 = 4’ü istenen kişi sayısı sanmak; 4 iki yön sayısının farkıdır.','Toplam ve fark','Kişi sayısı toplamı 10, fiyat etkisinden sayı farkı 4 bulunur; birlikte büyük grup 7’yi belirler.','12 kişi iki menü arasında değişiyor, üst menü 10 TL pahalı ve toplam 40 TL artıyor. Üste geçen kaç kişi?',['4','5','6','7','8'],4,'x + y12, x − y4; x8.');
M(135,'Kat artışından yıkılan bina türleri','Yüzde problemleri',51,'95 binanın başlangıç 2–3 kat dağılımını ve 15 binanın 5 kata dönüşümünde oluşan 34 kat artışı iki aşamada çözer.',['Başlangıç 3 katlı x ise toplam 2·95 + x = 240; x = 50.','Yıkılan 2 katlı a,3 katlı b için a + b = 15 ve artış 3a + 2b = 34’tür.'],['3(a + b) − b = 34; 45 − b = 34, b = 11 üç katlı bina yıkılmıştır.','Yeni 5 katlılar 3 katlı sayılmadığından 3 katlı sayısı 50’den 39’a iner. Azalma 11/50 = %22; D.'],'Toplam bina sayısındaki değişimi sormuş gibi yapmak veya yeni 5 katlıları 3 katlı gruba eklemek.','Doğru yüzde tabanı','Azalma yüzdesinin paydası ilk 3 katlı bina sayısı 50’dir,95 toplam bina değildir.','40 eski üç katlı binadan 8’i yıkılıp beş katlı olursa üç katlı sayısı yüzde kaç azalır?',['10','15','20','25','30'],2,'Azalan 8, ilk 40; 8/40 = %20.');
M(136,'Fotoğraflardaki toplam görünme sayısı','Sayı problemleri',47,'Her fotoğrafta iki veya üç kardeş bulunmasını, üç kişinin 83 er görünmesinden oluşan 249 toplam katkıyla karşılaştırır.',['İki kardeşli fotoğraf 2, üç kardeşli fotoğraf 3 kişi görünümü sayılır.','Üç kişinin toplam görünümü 3 × 83 = 249’dur; fotoğraf sayısı 100’dür.'],['Üçlü fotoğraf x ise ikili 100 − x. 2(100 − x) + 3x = 249.','200 + x = 249; x = 49, C. Fotoğraf sayısıyla kişi görünme sayısı aynı büyüklük değildir.'],'83’ü ortak üçlü fotoğraf sayısı sanmak; 83 her kişinin ayrı bütün fotoğraflardaki görünümüdür.','Çift sayım','Aynı toplam bir yanda kişi bazında, diğer yanda fotoğraf türü bazında sayılır; eşitlenmeleri bilinmeyeni verir.','50 fotoğrafta 2 veya 3 kişi, toplam 130 görünüm var. Üç kişili kaç fotoğraf vardır?',['20','25','30','35','40'],2,'100 + x = 130; x = 30.');
M(137,'Mola öncesi yolun iki farklı tamamlanışı','Kesir problemleri',48,'İkinci senaryoda eski yolun üçte biri daha koşulmasını 4x/3 toplamına çevirip ilk senaryoyla ortak parkur uzunluğunu bulur.',['Mola öncesi x, parkur L olsun.','x + 240 = 7L/12 ve x + x/3 = 3L/5 koşulları farklı varsayımsal devamları anlatır.'],['İkinci eşitlikten x = 9L/20.','İlke koyunca 240 = (7/12 − 9/20)L = (2/15)L; L = 1800 m, C. İki senaryo arka arkaya yapılan koşular değildir.'],'240 metreyi önce koşulan yolun üçte biri sanmak veya 7/12 ile 3/5 arasındaki farkı 240’a eşitlemek.','Ortak bilinmeyen','İki varsayımsal devam aynı x başlangıcını paylaşır; bir eşitlikte x i L cinsinden yazmak sistemi küçültür.','Koşulan x yol, parkurun 2/5’i. x in yarısı daha koşulursa toplam parkurun ne kadarı olur?',['1/5','2/5','1/2','3/5','4/5'],3,'1,5 × 2/5 = 3/5.');
M(138,'Ters oranlı kutular ve tamsayı sayıları','Oran orantı',45,'A = 2B = 3C = 4D eşitliğini ortak 12 katsayısıyla en küçük tamsayı oranına dönüştürüp 8 topun hangi kutuda olabileceğini sınar.',['A, B, C, D oranı 12:6:4:3’tür.','Bütün kutuların top sayıları tam olduğundan bu en sade oran ortak pozitif tamsayıyla çarpılır.'],['Sayılar 12t,6t,4t,3t. 8 yalnız 4t ile t = 2 olduğunda tamsayı çözüm verir.','Toplam 25t = 50 top, E. 8’i A’ya koymak diğer kutularda kesirli top doğurur.'],'A’nın kat ilişkilerini doğru orantı 2:3:4 sanmak veya kesirli top sayısını kabul etmek.','EKOK ile ölçek','2,3,4’ün ortak katı 12 tüm oranları tamsayı yazar; bir kutudaki 8 ortak ölçeği belirler.','Kutular 6t,3t,2t oranında, son kutuda 10 top var. Toplam kaçtır?',['30','40','45','50','55'],4,'2t10’dan t5; toplam 11t = 55.');
M(139,'Yol tabelalarında ortak parçaları çıkarmak','Hareket ve uzaklık',54,'D ve E’de verilen farklı hedef uzaklıklarını yol ayrımı etrafında ortak parçalara ayırarak C–B ile C–A farkını bulur.',['Ortak kavşaktan C’ye c, D’ye d, E’ye e; D–A’a, E–B b olsun.','d + c = 40, e + c = 66, d + e + b = 94, e + d + a = 106’dır.'],['İlk iki denklemden e − d = 26, son ikiden b − a = −12.','CB − CA = (e + b) − (d + a) = 26 − 12 = 14 km, E. C’ye ortak c parçası farkta yok olur.'],'Tabeladaki 94 ve 106’yı doğrudan C’den uzaklık sanmak; ölçümlerin başlangıç noktaları farklıdır.','Ağda ortak kenar','Mesafe toplamlarını parçalara ayırmak görünmeyen uzunlukları tek tek bulmadan istenen farkı sadeleştirmeyi sağlar.','Kavşak–B yolu 30 km, kavşak–A yolu 22 km, C–kavşak 17 km. CB − CA kaç km?',['5','8','13','17','25'],1,'Ortak 17 km farkta silinir; 30 − 22 = 8.');
M(140,'Eş mavi sayısı, farklı doluluk oranı','Oran orantı',45,'3:4:6 oranlı kalemlik toplamlarını bulup aynı mavi sayısının 1/2 ve 1/3 paylarını oluşturduğu iki toplamı eşleştirir.',['3 + 4 + 6 = 13 birim 78 kalemse birim 6; toplamlar 18,24,36’dır.','Mavi sayısı m eşitse oranları 1/2,1/3 olan kalemlik toplamları 2m ve 3m olmalıdır.'],['18,24,36 içinde 3/2 oranlı çift 24 ve 36’dır.','2m = 24,3m = 36; her kalemlikte 12 mavi, üçünde 36 mavi vardır, E. 18 ve 36 çifti oran 2 verir, uymaz.'],'Bir kalemliğin mavi sayısını toplam mavi diye cevaplamak veya 3:4:6 oranını mavi sayıları arasında sanmak.','Ortak pay','Aynı paya sahip iki kesrin paydaları oranlardan ters biçimde belirlenir; eş mavi sayısı bağlayıcı bilgidir.','İki kutuda aynı 8 mavi top var; oranlar 1/2 ve 1/4. Toplam top sayıları toplamı kaçtır?',['24','32','40','48','64'],3,'Kutular 16 ve 32 top; toplam 48.');
M(141,'Ağaç yaşını iki öğrenci grubuyla saymak','Yaş problemleri',49,'Beş yılda yalnız beş yaş büyüyen ağacın, ilk grupta yedişer ikinci grupta onar yaş toplamlarıyla eşitliğini kurar.',['İkinci grupta n kişi, ilk grupta n + 10 kişi vardır.','2015 ağaç yaşı 7(n + 10),2020 yaşı 10n; aralarındaki fark 5’tir.'],['7(n + 10) + 5 = 10n; 75 = 3n, n = 25.','2020 ağaç yaşı 10 × 25 = 250; D. İlk gruptaki öğrenciler 2020’de yeniden yaşlandırılıp sayılmaz; farklı grup ziyaretidir.'],'İki grubun yaş toplamına ayrı ayrı beşer eklemek; beş yıl yalnız aynı ağacın yaşına eklenir.','Ortak nesnenin zaman değişimi','İki ayrı toplam aynı ağacın farklı tarihteki yaşını ölçtüğünden aradaki ilişki sabit beş yıllık farktır.','Bir ağacın yaşı ilk yıl 6n, üç yıl sonra 9n − 6. n kaçtır?',['1','2','3','4','5'],2,'6n + 3 = 9n − 6; 3n = 9, n = 3.');
M(142,'Silinen klasördeki soru sayısı','Sayı problemleri',47,'Klasör, test ve soru katmanlarını çarpıp tek alt klasörün tüm p testleriyle silinmesini toplamdan çıkarır.',['Başlangıç 5 ana konu × n alt klasör × p test × 12 soru içerir.','Silinen bir alt klasörde p test ve 12p soru vardır.'],['İlk toplam 60 np, son toplam 60 np − 12p.','Ortak çarpanla 12p(5n − 1); D. Silinen bir konu klasörü değil, Olasılık içindeki tek alt klasördür.'],'Yalnız 12 soru veya bütün n alt klasörü çıkarmak; silme eyleminin düzeyi doğru okunmalıdır.','Çarpma ilkesi ve çıkarma','Hiyerarşide silinen düğümün bütün alt içeriği çıkarılır; hangi katmanın değiştiği toplam katsayıyı belirler.','4 konuda 3 er alt klasör, her birinde 2 test, her testte 10 soru var. Bir alt klasör silinirse kaç soru kalır?',['200','210','220','230','240'],2,'Başlangıç 240, silinen 20; 220 soru kalır.');
M(143,'Vazonun yapıldığı ve bulunduğu yıllar','Yaş problemleri',49,'Vazonun bulunma yılını Faruk un doğum yılıyla eşleyip 300 yıllık farkı üretim yılına geriye taşır.',['Faruk yaşı x ise doğum ve vazonun bulunma yılı 2020 − x tir.','Vazo bulunduğunda 300 yaşında olduğundan yapım yılı 1720 − x olur.'],['Faruk un yaşının 39 katı yapım yılına eşit:39x = 1720 − x.','40x = 1720, x = 43; C. Vazonun bulunduğu yıl ile yapıldığı yıl aynı değildir; 300 yıl bu ikisini ayırır.'],'Vazo 2020’de 300 yaşında sanmak veya bulunma yılını yapım yılı yerine doğum yılına eşitlemeden kullanmak.','Takvim yılı ve yaş','Takvim yılıyla yaş farklı niceliklerdir; bir olay yılına ulaşmak için referans yıldan geçen süre çıkarılır.','2025’te 30 yaşındaki kişinin doğumunda 200 yaşında bir eser bulunmuş. Eser hangi yıl yapılmıştır?',['1765','1775','1785','1795','1805'],3,'Doğum 1995, yapım 1995 − 200 = 1795.');
M(144,'Kapalı rakam kümesinde rakam toplamı','Sayı basamakları',16,'1,4,7 rakamlarıyla yazılan dokuz iki basamaklı adayın toplamının yine yalnız aynı rakamlardan oluşmasını sınar.',['Tekrarlı rakama izin vardır; 11,14,...,77 toplam dokuz adaydır.','İki rakam toplamı en az 2, en fazla 14 olduğundan izinli sonuçlar bu aralıkta yalnız 4,7,11,14 olabilir.'],['Olası toplamlar 2,5,8,11,14’tür; izinli olan 11 ve 14.','11 toplamını 47 ve 74,14 toplamını 77 verir. Üç dosdoğru sayı vardır; C. 11’in rakamları 1 olduğu için sonuç olarak uygundur.'],'Rakamların farklı olması şartını eklemek veya toplamın mutlaka tek rakam olması gerektiğini varsaymak.','Sonlu kümede tarama','Yeni tanımı sayının rakamlarıyla rakam toplamının rakamlarına ayrı uygulamak gerekir; bu iki koşul birbirinden bağımsızdır.','Yalnız 1 ve 3 ile yazılan iki basamaklı sayılardan rakam toplamı 4 olan kaç tane vardır?',['1','2','3','4','5'],1,'13 ve 31 toplam 4 verir; iki sayı.');
M(145,'Üçüncü ve yedinci geçiş arası dört tur','Hareket problemleri',54,'Aynı noktadan ardışık geçişlerin periyot farkını kullanıp üçüncü geçişten iki tur geri giderek ilk geçiş zamanını bulur.',['B’den üçüncü ile yedinci geçiş arasında dört tam tur vardır.','Sabit hız ve aynı yönde hareket tur süresini sabit kılar.'],['8 − 3 = 5 dakika, dört tur; bir tur 75 saniye.','Üçüncü geçiş 180 saniye ise ilk geçiş 180 − 2 × 75 = 30 saniye; A. İlk geçiş zamanı başlangıç A konumuna bağlıdır, tam tur olmak zorunda değildir.'],'Üçüncü ile yedinci arasını yedi veya üç tur saymak; olay sıra numaralarının farkı alınır.','Periyodik zaman dizisi','Geçiş zamanları aritmetik dizi oluşturur; ortak fark tur süresidir ve önceki terim geriye bulunur.','İkinci geçiş 100, dördüncü geçiş 220 saniyede. İlk geçiş kaçıncı saniyede?',['20','30','40','50','60'],2,'İki tur 120, bir tur 60; ilk 100 − 60 = 40 saniye.');
M(146,'Sabit indirimle yüzde indirimi eşlemek','Yüzde problemleri',51,'9 TL azalmanın ilk tutarın%15 ine eşit olduğunu kullanır; son ödeme ile yüzde tabanını ayırır.',['İndirim yüzdesi internet sitesindeki eski toplam üzerinden verilir.','9 TL bu eski toplamın 0,15 katıdır; ödenen yeni tutar%85 idir.'],['Eski toplam T için 0,15T = 9; T = 60 TL.','Mobil ödeme 60 − 9 = 51 TL; E. 9/0,85 işlemi eski toplamı vermez, çünkü 9 yeni tutarın%85’i değildir.'],'%15’i son ödemeye uygulamak veya 9 TL’yi yeni fiyat olarak almak.','Yüzde tabanı','Aynı mutlak fark, yüzdesi hangi tutara göre ölçülüyorsa o tutarı belirler; önce eski fiyat bulunur.','12 TL indirim eski fiyatın%20 si. Yeni fiyat kaç TL?',['36','42','48','54','60'],2,'Eski 60, yeni 60 − 12 = 48 TL.');
M(147,'Ters yazılan daire numarasını sınırlandırmak','Sayı basamakları',16,'İki apartmanın 72 ve 88 sınırlarından gerçek numarayı 73–88’e, tamamen olmayan ters numarayı 88 üstüne sınırlar.',['Gerçek numara 72 lik apartmanda yok,88 likte vardır; 73 ≤ N ≤ 88.','Yanlış yazılan ters numara iki apartmanda da yoksa 88’den büyüktür.'],['Ters numaranın onlar rakamı 9 olmalı; gerçek numara 9 ile biter.','73–88 aralığında bu koşulu yalnız 79 sağlar; tersi 97. Rakam toplamı 7 + 9 = 16; E. 89 gerçek aralığın dışındadır.'],'İlk yanlış apartmanın 72 veya 88 olduğunu rastgele seçmek yerine iki yokluk bilgisini birlikte kullanmamak.','Basamak değişimi ve aralık','Rakam çevrilmesi sayının değerini farklı aralığa taşır; iki aralık aynı rakamları güçlü biçimde sınırlar.','Gerçek iki basamaklı sayı 60–75 arasında, tersi 90’dan büyük. Hangisi olabilir?',['61','64','69','72','75'],2,'69’un tersi 96; diğer tersler 90’ı aşmaz.');
M(148,'İki içecek kümesinin ortak yüzdesi','Kümeler',68,'Soğuk ve sıcak alanların toplamından en az bir içecek alanların oranını çıkararak ortak gruba alt–üst sınır bulur.',['Birleşim, hiç almayan%0–4 olduğundan%96–100 arasındadır.','Kesişim yüzdesi soğuk + sıcak − birleşim ile bulunur.'],['En küçük ortak 52 + 67 − 100 = %19.','En büyük ortak 60 + 72 − 96 = %36. İstenen aralık%19–%36; C. Soğuk ve sıcak grupları ayrık kabul edilemez.'],'Yüzdeler toplamını 100’e eşitleyip hiç içmeyenleri unutmak veya ortak oranı yalnız büyük grubun fazlası sanmak.','Dahil etme–çıkarma','Ortak kişiler iki grup toplamında iki kez sayılır; birleşim çıkınca tam bir kez kalan katkı kesişimdir.','A%60, B%70 ve birleşim%95 ise ortak yüzde kaçtır?',['25','30','35','40','45'],2,'60 + 70 − 95 = %35.');
M(149,'Bir yanlış Fahrenheit kaydından günü bulmak','Ortalama ve dönüşüm',47,'Doğru beş günlük toplamla yanlış ortalamanın toplamını karşılaştırıp tek günkü F − C hatasından sıcaklığı bulur.',['Doğru toplam 23 + 27 + 25 + 20 + 26 = 121 °C.','Yanlış ortalama 33,8 olduğundan kayıt toplamı 169; tek hata 48 derecelik sayı farkıdır.'],['F − C = (9/5 − 1)C + 32 = 0,8C+32.','0,8C+32 = 48’den C = 20 °C. Tabloda 20 Perşembe günüdür; D. Ortalamadaki 9,6 fark toplamda 48 yapar.'],'Ortalama farkını tek kaydın hatası sanmak veya Fahrenheit formülündeki 32 sabitini atlamak.','Ortalama toplamı','Bir kaydın hatası ortalamaya 1/n oranında yansır; önce toplam hatasına dönmek dönüşüm denklemini kurar.','Dört günün doğru toplamı 80, yanlış ortalaması 25 ise tek kayıttaki sayı hatası kaçtır?',['5','10','15','20','25'],3,'Yanlış toplam 100; hata 100 − 80 = 20.');
M(150,'Gidiş–dönüşte çapraz firma grupları','Denklem sistemi',33,'A ile gidip B ile dönenlerle B ile gidip A ile dönenleri toplam farklı firma bilgisi ve marjinal sayılarla ayırır.',['Gidişte A firmasını 75 kişi seçtiyse B firmasını 60 kişi seçmiştir.','AB = x, BA = y alındığında farklı firmalar x + y = 86 olur.'],['Dönüşte B firmasını 90 kişi seçtiğinden BB = 90 − x. Gidiş B toplamı(90 − x) + y = 60; x − y = 30.','x + y = 86 ile y = 28 bulunur; B ile gidip A ile dönen 28 kişi, C.'],'86’yı istenen tek çapraz grup sanmak; iki farklı yöndeki grup birlikte sayılmıştır.','İki yönlü tablo','Satır ve sütun toplamları aynı dört hücreyi farklı biçimde sınırlar; çapraz toplam üçüncü bağımsız bilgidir.','AB + BA = 50, AB − BA = 14 ise BA kaçtır?',['14','16','18','20','22'],2,'İki eşitliği çıkarınca 2 BA = 36; BA = 18.');
M(151,'İki ve üç günlük çalışan döngüleri','Periyodik problemler',25,'Üç günde bir gelen grubun 1. ve 4. gündeki katkısı aynı olduğundan farkın iki günlük gruplar arasındaki farkı verdiğini kullanır.',['İki günlük çalışanlar tek ve çift günlerde A, B gruplarına ayrılır.','Üç günlük çalışanların 1–4 aynı fazı,2–5 aynı fazı paylaşır.'],['İlk gün A + C = 22, dördüncü B + C = 26; B − A = 4.','İkinci B + D = 19 ise beşinci A + D = 19 − 4 = 15; B. Toplam personel veya tüm fazlar tek tek bulunmadan sonuç çıkar.'],'Bütün çalışanların birinci gün aynı anda döngüye başladığını varsaymak; bu durumda verilen farklı sayılar açıklanamaz.','Ortak fazı yok etme','Aynı periyodik katkıyı içeren günleri çıkarmak öteki grubun farkını ayırır; sonra bu fark başka faza taşınır.','1. gün A + C = 18,4. gün B + C = 23,2. gün B + D = 20.5. gün A + D kaçtır?',['10','12','15','18','20'],2,'B − A = 5; A + D = 20 − 5 = 15.');
M(152,'Trafik grafiğinde eşit yolculuk süreleri','Doğrusal grafik',31,'07–08 artan ve 08–09 azalan iki doğrusal süre grafiğinde bir saat arayla çıkanların sürelerini aynı dakika değişkeninde eşitler.',['08.00’den x dakika sonraki süre 36 − x/10 dakikadır.','Bir saat önce 07.00’den x dakika sonraki süre 24 + x/5 dakikadır.'],['36 − x/10 = 24 + x/5; 12 = 3x/10, x = 40.','Gerçek çıkış 08.40, süre 32 dakika; varış 09.12, A. Sürelerin eşitliği varış saatlerinin eşitliği değildir.'],'Grafik dikey eksenini doğrudan varış saati sanmak veya x i saat birimiyle alıp dakika eğimleriyle karıştırmak.','Doğrusal enterpolasyon','İki uç noktadan eğimler hesaplanır; ortak yatay kayma x ile iki farklı doğru karşılaştırılabilir.','08.00’de 40 dakika,09.00’da 28 dakika doğrusal süre varsa 08.30 daki süre kaçtır?',['28','30','32','34','36'],3,'Yarım saatte 12 dakikalık azalmanın yarısı 6; 40 − 6 = 34 dakika.');
M(153,'Ardışık tek sayılarda onluk geçişi','Sayı basamakları',16,'AB ve BC’nin ardışık tek doğal sayı olması nedeniyle farklarını 2 alır; farklı rakam koşulunun zorladığı onluk geçişini bulur.',['BC = AB + 2’dir; ardışık tek sayılar arasında 2 fark vardır.','B ≠ 9 ise onlar basamağı değişmez, A = B olur; bu farklı rakam koşuluna aykırıdır.'],['Bu yüzden B = 9. AB’ye 2 eklenince birler 1, onlar A + 1 olur; BC’nin onlar rakamı 9 olduğundan A = 8.','Sayılar 89 ve 91; A = 8, B = 9, C = 1. Rakam toplamı 18, D. 90 çift olduğu için ikinci sayı olamaz.'],'Ardışık ifadesini tek sözcüğünü atlayarak 1 farkla yorumlamak; 89 ve 90 sonucu bu hatadan doğar.','Basamak taşıması','İki eklenince 9 birler basamağı 11 olur; bir elde, onlar basamağını değiştirir ve yeni birler 1 olur.','89’dan sonraki ardışık tek sayı hangisidir?',['90','91','92','93','95'],1,'Tek sayılar ikişer artar; 89 + 2 = 91.');
M(154,'Budamadan önce ve sonra farklı büyüme','Denklem kurma',31,'11 haftayı 2 ve 3 cm büyüyen dönemlere ayırıp tek 25 cm kesilmeyi toplam boy bilançosuna ekler.',['Budama öncesi t hafta, sonrası 11 − t haftadır.','Son boy 40 + 2t − 25 + 3(11 − t) olarak yazılır.'],['Bu boy 40 olduğundan 48 − t = 40; t = 8 hafta.','Budamanın hemen sonrası 40 + 16 − 25 = 31 cm; C. Sonraki üç haftada 9 cm uzayıp 40’a dönmesi kontrol edilir.'],'25 cm yi her hafta kayıp gibi almak veya budamadan sonraki boy yerine budama öncesi 56’yı cevaplamak.','Parçalı doğrusal değişim','Farklı dönemlerin hızları ayrı sürelerle çarpılır; tek seferlik kesilme bunlardan bağımsız sabit terimdir.','30 cm bitki 5 hafta 2 cm uzayıp 15 cm kesiliyor. Hemen sonraki boy kaç cm?',['20','23','25','28','30'],2,'30 + 5 × 2 − 15 = 25 cm.');
M(155,'Video hızında izlenen içerik miktarı','Oran orantı',46,'İki saatlik duvar süresinden 20 dakikalık arayı çıkarıp 1,25 ve 1,5 hızların gerçek içerik dakikalarını toplar.',['Toplam izleme süresi 120 − 20 = 100 dakikadır.','Hız, normal video süresi/gerçek süre olduğundan içerik = hız × süre dir.'],['İlk izleme t, ikinci 100 − t dakika; 1,25t + 1,5(100 − t) = 135.','150 − 0,25t = 135; t = 60.12.00’den 60 dakika sonra mola 13.00’te başlar; C.'],'Hızla izlenen süreyi tekrar bölmek veya 20 dakikalık molayı video izlenmiş gibi saymak.','Ağırlıklı hız','İki dönemdeki içerik katkıları kendi hızlarıyla ağırlıklandırılır; ortalama hız toplam gerçek izleme süresine göre hesaplanır.','1,5 hızda 40 dakika izlenen video bölümünün normal süresi kaçtır?',['25','30','40','50','60'],4,'Normal içerik 1,5 × 40 = 60 dakikadır.');
M(156,'Koltuk etiketi sırayla sağdaki toplamı','Sayı problemleri',47,'Etiket numarasının sütun sıra numarası olmadığını; bulunduğu sıra ile sağında kalan koltuk sayısının toplamı olduğunu uygular.',['Her sırada k koltuk varsa ilk koltuğun sağında k − 1 vardır.','Son sıranın ikinci koltuğunun sağında k − 2 koltuk kalır.'],['Dördüncü sıradaki ilk sarı koltuk 4 + k − 1 = 15; k = 12.','Son sıra n için n + 12 − 2 = 21; n = 11. Toplam 11 × 12 = 132 koltuk; B.'],'Sarı 15 etiketini 15 koltuk olarak almak veya ikinci koltuğun sağında k − 1 saymak.','İndeks ve kalan miktar','Bir satırda konum ilerledikçe sağdaki miktar azalır; etiket bu farkı satır numarasına ekler.','Her sırada 10 koltuk; 7. sıranın 3. koltuğunun etiketi nedir?',['12','13','14','15','16'],2,'Sağında 10 − 3 = 7; etiket 7 + 7 = 14.');
M(157,'Anketin kısmi sayfasından toplamına','Kesir problemleri',48,'İkinci sayfada 3 sorunun çözülmesini, bir tam sayfa artı 3 soru olarak%20 tamamlanmaya eşitler.',['Sayfa başına q soru; toplam 6q sorudur.','İkinci sayfada 3 soruya gelince q + 3 soru çözülmüştür.'],['q + 3 = 0,20·6q; 3 = 0,2q, q = 15.','Beşinci sayfada 3 soru 4 × 15 + 3 = 63 eder; toplam 90 içinde 63/90 = %70, E.'],'İkinci sayfaya gelmeyi iki tam sayfa çözmek sanmak veya%20’yi sayfa sayısı oranına doğrudan uygulamak.','Tam parça ve kalan','Bir dönüm noktasındaki toplam, biten sayfaların katkısıyla mevcut sayfadaki ilerlemenin toplamıdır.','Her sayfa 20 soru,5 sayfa var. 4. sayfada 10 soru çözülünce yüzde kaç tamamlanır?',['50','60','65','70','80'],3,'3 × 20 + 10 = 70 soru; toplam 100,%70.');
M(158,'Saat hanesindeki 15’in süre payı','Zaman problemleri',47,'Toplantının saat 15 aralığında geçen bölümünü toplam 108 dakikanın%25’i olarak bulup bitişten başlangıca geri gider.',['Saat hanesi 15,15.00–15.59 aralığını gösterir.','Toplantı 15 hanesi görünürken bittiğinden o aralıktaki süre 15.00’dan bitişe kadardır.'],['108 × 0,25 = 27 dakika; toplantı 15.27’de bitmiştir.','15.27’den 108 dakika çıkarılır:13.39. Başlangıç A seçeneğidir; 15 sayısı dakika hanesindeki 15 değildir.'],'Toplantı 15.00’te bitti sanmak veya 27 dakikayı başlangıçtan önceki bölüm gibi yorumlamak.','Zaman aralığı kesişimi','Toplantının belli saat dilimindeki süresi bütün sürenin bir parçasıdır; hanenin görünmesi bir aralığı tanımlar.','100 dakika toplantının%30 u16 saat hanesinde geçip 16.30’da bitiyor. Başlangıç kaçtır?',['14.30','14.40','14.50','15.00','15.10'],2,'16.30 − 100 dakika = 14.50; 16.00 sonrası 30 dakika koşulu da sağlanır.');
M(159,'Ev yaşının iki insan yaşına eşitliği','Yaş problemleri',49,'Aynı evin 1990,2000,2020 yaşlarını ortak yapım yılıyla yazıp sonuncuyu ilk ikisinin toplamına eşitler.',['Yapım yılı y ise evin 1990 yaşı 1990 − y,2000 yaşı 2000 − y.','Bu değerler Ayşe ve eşinin bugünkü yaşlarıdır; 2020 ev yaşı onların toplamıdır.'],['2020 − y = (1990 − y) + (2000 − y).','2020 − y = 3990 − 2y den y = 1970; C. Bugünkü yılın ayrıca bilinmesi gerekmez, çünkü insan yaşları verilen eşitliklerle temsil edilir.'],'1990 ve 2000’i kişilerin doğum yılları sanmak veya iki insanı 2020’ye kadar yeniden yaşlandırmak.','Ortak referans yılı','Ev aynı nesne olduğundan bütün yaşlar aynı bilinmeyen yıldan çıkarılır; eşitlikler kişisel yaş bilinmeyenlerini yok eder.','Bir evin 2000 ve 2010 yaşları toplamı 2030 yaşına eşitse yapım yılı nedir?',['1970','1980','1990','2000','2010'],1,'2030 − y = 4010 − 2y; y = 1980.');
M(160,'Uzaklık grafiğinde eğim değişimi','Hareket problemleri',54,'Zıt yönlere giden iki kişinin toplam hızını ilk eğimden, okula erken varanın durması sonrası kalan hızını ikinci eğimden bulur.',['İlk 4 dakikada uzaklık 1400 m artar; iki hız toplamı 350 m/dk.','Sonraki 2 dakikada 300 m artar; hareketi süren kişinin hızı 150 m/dk dır.'],['Duranın hızı 350 − 150 = 200 m/dk, okul yolu 4 × 200 = 800 m.','Devam edenin yolu 6 × 150 = 900 m; daha uzak okul Esra nın olduğundan Burcu erken duran kişidir. Burcu 800 m; E.'],'İlk eğimi tek kişinin hızı sanmak veya Esra daha uzakta diye mutlaka daha hızlı yürüdüğünü varsaymak.','Parçalı hareket','Grafik eğimindeki azalma bir kişinin varıp durduğunu gösterir; hangi kişinin olduğu yol uzunluğu karşılaştırmasıyla belirlenir.','Zıt yürüyen iki hız toplamı 300, biri durunca eğim 120 m/dk. Duranın hızı kaçtır?',['120','150','180','240','300'],2,'Toplamdan kalan hız çıkarılır; 300 − 120 = 180 m/dk.');
M(161,'Ziyaret edilen ve edilmeyen müzeler','Oran orantı',46,'12 yeni ziyaretin hem gidilenleri artırıp hem gidilmeyenleri azaltmasını iki oran arasında birlikte hesaba katar.',['Başlangıç gidilen x, gidilmeyen 2x; toplam 3x tir.','Sonraki durum gidilen x + 12, gidilmeyen 2x − 12 olur; toplam değişmez.'],['(x + 12)/(2x − 12) = 2/3; 3x + 36 = 4x − 24.','x = 60, toplam 3x = 180 müze; D. 12 yalnız paya eklenmez, paydadan da çıkarılır.'],'Gidilmeyen sayısını sabit tutmak veya 1/2’yi toplam müzeler içindeki ziyaret oranı sanmak.','Bölümler arası aktarım','İki gruplu sabit evrende birine geçen nesne ötekinden çıkar; oranın iki tarafı eşzamanlı değişir.','Gidilen 20, gidilmeyen 40 müze var. 10 yeni ziyaret sonrası oran nedir?',['1/3','1/2','2/3','1','3/2'],3,'Yeni sayılar 30 ve 30; oran 1.');
M(162,'Tariften artan fındık','Karışım problemleri',53,'İlk imalathanede artan 9 kg şekeri başlangıç 21 kg dan çıkararak kullanılan oranı bulur, ikinci imalathaneye uygular.',['İlk üretimde şeker 21 − 9 = 12 kg, fındık 42 kg kullanılır.','Tarif fındık/şeker = 42/12 = 7/2’dir; ikinci üretimde yalnız fındık arttığı için 16 kg şekerin tamamı kullanılır.'],['16 kg şeker için 16 × 7/2 = 56 kg fındık gerekir.','Başlangıç 64 olduğundan 64 − 56 = 8 kg fındık artar; B. 42/21 oranı artan şekeri içerdiği için tarif oranı değildir.'],'Başlangıç stok oranını karışım oranı sanmak veya ikinci üretimde de 9 kg şeker arttığını varsaymak.','Kullanılan miktar oranı','Sabit tarif yalnız gerçekten karıştırılan maddeleri ilişkilendirir; stok eksi artık dönüşümü ilk adımdır.','Tarifte 3 kg fındığa 1 kg şeker gerekiyor. 8 kg şekerde 30 kg fındıktan kaç kg artar?',['3','4','5','6','8'],3,'Gereken 24 kg; 30 − 24 = 6 kg artar.');
M(163,'Fırındaki üç zaman aralığı','Zaman problemleri',47,'Pasta ve kekin aynı 12.30 bitişini bulup böreğin 40 dakikalık aralığını 15 dakika üçlü ve 15 dakika tekli koşullarıyla seçer.',['Pasta 11.55 + 35 = 12.30, kek 12.05 + 25 = 12.30’da çıkar.','Üçünün birlikte olduğu aralık, börekle 12.05–12.30 kesişimidir.'],['Üçlü süre 15 için börek 11.40–12.20 veya 12.15–12.55 olabilir.','İlkinde yalnız börek 11.40–11.55 arası 15 dakika; ikincide tekli süre 35 olur. Doğru başlangıç 11.40, son bitiş 12.30; 50 dakika, A.'],'Yiyecek sürelerini toplamak veya üçlü süre 15’ten böreğin mutlaka en son girdiğini varsaymak.','Aralık kesişimi','Birlikte bulunma ve tek bulunma farklı zaman aralığı kesişimleriyle ölçülür; ikinci koşul iki adayı ayırır.','Pasta 10.00–10.30, kek 10.10–10.30. İkisinin birlikte süresi kaç dakika?',['10','15','20','25','30'],2,'Ortak aralık 10.10–10.30; 20 dakika.');
M(164,'Hafta içi ve sonu farklı birikim','Periyodik problemler',25,'Haftalık 150 TL birikimden üç haftalık 450 TL’yi ayırıp 500’e ilk erişimin Cumartesi olması için kalan gün desenini sınar.',['Bir haftada 5 × 20 + 2 × 25 = 150 TL birikir.','Üç tam hafta 450 TL; sonraki eş günlü döngüde en az 50 TL daha gerekir.'],['Başlangıç Perşembe ise üçüncü haftadan sonra Perşembe 20, Cuma 20 ile 490 TL olur.','Cumartesi 25 eklenince 515 TL ile eşik ilk kez aşılır. Diğer başlangıç günleri başka gün eşiğe ulaşır; D.'],'Cumartesi para tam 500 olmalı sanmak; söz en az 500 olduğundan 515’de uygundur.','Eşikli periyodik toplam','Tam haftalar çıkarılınca uzun günlük çizelge birkaç günlük kalan toplama iner; ilk erişim koşulu bir önceki günü de sınar.','Haftalık 100 TL birikimde üç hafta sonunda 300 TL var. Hedef 350, sonraki üç gün 20,20,20. İlk hangi gün hedef geçilir?',['İlk','İkinci','Üçüncü','Dördüncü','Hiç'],2,'Toplamlar 320,340,360; ilk ulaşım üçüncü gün.');
M(165,'Balon sayısı değil boşluk sayısı','Oran orantı',46,'İki sabit uç balonun arasına iki veya dört balon eklenince toplam aralıkların 3 ve 5 oluşmasını kullanır.',['Uçlar arası uzunluk L sabittir.','İki yeni balon 3 eş boşluk, dört yeni balon 5 eş boşluk oluşturur.'],['Beyaz durumda L/3, sarı durumda L/5 aralık vardır.','L/3 − L/5 = 18;2L/15 = 18, L = 135 cm, A. İki uç balon da aralık sınırları olarak hesaba katılır.'],'Uzunluğu 2 ve 4’e bölmek; eklenen nesne sayısı aralık sayısına eşit değildir.','Eş bölme modeli','Bir doğru parçasına k iç nokta yerleştirilince k + 1 alt parça oluşur; gündelik düzenleme bu temel geometriye döner.','Uçlar arasına 3 balon eklenince aralık 20 cm. Uç mesafe kaç cm?',['40','60','80','100','120'],2,'3 iç nokta 4 aralık verir; 4 × 20 = 80 cm.');
M(166,'İki yerleşimde eş yükseklik çizgileri','Denklem sistemi',33,'Şekillerde oyuncak tepesiyle raf düzeyinin eşleşmelerini okuyup raf yüksekliği ve nesne boylarını ayrı değişkenlerle kurar.',['Sol raf 18, orta raf y, sağ raf z; ayı a, at h, kaktüs c olsun.','İlk şekil 18 + a = y ve y + h = z + c; ikinci 18 + c = y = z + h verir.'],['18 + a = 18 + c den a = c. İki son eşitlikten c = 2h.','a + h + c = 15 olduğundan 5h = 15; h = 3, a = c = 6. Raflar y = 24, z = 21; toplam 45, A. Nesne boyu raf yüksekliğine eklenir.'],'Kesikli çizgiyi yanlış nesnenin tabanına bağlamak; çizgiler yalnız tam aynı yükseklikteki noktaları eşler.','Çoklu temsilde aynı değişken','Nesneler raf değiştirse de kendi boyları ve rafların yükseklikleri sabit kalır; iki görüntü bu sabitleri birlikte belirler.','Raf 20 cm, nesne 7 cm; nesnenin tepesi ikinci rafla aynı hizada. İkinci raf kaç cm?',['13','20','24','27','34'],3,'Yükseklik 20 + 7 = 27 cm.');
M(167,'Tekne kapasitesinde tamsayı oranı','Oran orantı',46,'İlk iki yolcu sayısını 4k ve 5k yazıp her seferde 20–35 sınırı ile toplam 91 koşulunu birlikte denetler.',['İlk sefer 4k, ikinci 5k, üçüncü 91 − 9k dir.','Sayılar tam ve 4,5 aralarında asal olduğundan k pozitif tamsayıdır.'],['İlk iki kapasiteden 5 ≤ k ≤ 7. k = 5 üçüncü 46, k = 6 üçüncü 37 yapar; ikisi 35’i aşar.','k = 7 üçüncü 91 − 63 = 28 verir; C. İlk 28, ikinci 35’de kapasiteye uygundur.'],'Toplam 91’i üçe eşit bölmek veya 35 sınırını yalnız ilk iki seferde kontrol etmek.','Tamsayılı fizibilite','Oran sürekli birçok çözüm sunsa da tamsayılılık ve kapasite sınırları üç adaydan tekini bırakır.','Sefer sayıları 3k,4k, toplam 56 ve k tamsayı. İkinci sefer kaç kişidir?',['21','24','28','32','35'],3,'7k = 56; k = 8, ikinci 4k = 32.');
M(168,'Kahve makinesinde kesin çalışan bardak','Eşitsizlikler',32,'Çalışan 14,5 cm ve çalışmayan 15,2 cm bardaktan makinenin sabit yüksekliğini sınırlar; her adayın bütün bu aralıkta çalışmasını arar.',['Makine yüksekliği H ise 14,5 bardakta 26 ≤ H ≤ 26,9.','15,2 bardak çalışmadığı için H,26,7–27,6 dışında; birlikte 26 ≤ H < 26,7.'],['14,4 bardak için izinli H aralığı 25,9–26,8 olup bulunan aralığın tamamını kapsar.','14,2 üst uçta,14,6 alt uçta çalışmayabilir. Yalnız II kesin çalışır; B. Mümkün olmakla kesinlik farklıdır.'],'Bir örnek H seçip çalışan bütün bardakları kesin diye işaretlemek; her mümkün makine yüksekliği denenmiş olmalıdır.','Aralık içerilmesi','Kesin çalışma, makinenin olası yükseklik kümesinin bardak için izinli kümenin içinde kalmasıdır.','26 ≤ H ≤ 26,5 arasında, uygun boşluk 11–12 cm. 14,8 cm bardak kesin çalışır mı?',['Evet','Hayır, daima çalışmaz','Yalnız H = 26 iken','Yalnız H = 26,5 iken','Bilgi gereksiz'],0,'Boşluk 11,2–11,7 cm aralığındadır; tamamı 11–12 içinde.');
M(169,'Anket oyunda eski ve yeni yüzde','Yüzde problemleri',51,'Adana 3, Diyarbakır 2 oyunun toplam%25 olduğunu kullanıp başlangıç toplamını ve sonradan eklenen beş oyun etkisini hesaplar.',['Edirne%35, İstanbul%40 ise öteki iki ilin toplamı%25’tir.','3 + 2 = 5 oy başlangıç toplamının dörtte biridir; başlangıç 20 oy vardır.'],['Edirne başlangıç 7 oy. Ek 4 Edirne oyuyla 11, toplam 20 + 5 = 25 olur.','Son oran 11/25 = %44; E. Yeni yüzde için eski 20 değil yeni 25 paydası kullanılır.'],'Edirne%35’e doğrudan 4 puan eklemek; ek oylar pay ve paydayı birlikte değiştirir.','Dinamik oran','Yüzde temel aldığı toplamla birlikte değişir; mutlak oy sayısına geçmeden yüzde güncellenemez.','30 oydan 12 si A. A’ya 3, başka adaya 7 yeni oy gelirse A yüzdesi kaçtır?',['30','35','37,5','40','45'],2,'A’nın oyu 15, toplam oy 40; 15/40 = %37,5.');
M(170,'İki kişinin ortak kampanya alışverişi','Yüzde problemleri',51,'A mağazasında her kişinin indirimli kalem kutusu almasını, B mağazasında aynı tür ikililerin ikinci ürün indiriminden yararlanmasıyla karşılaştırır.',['A’da iki çanta 600 ve iki yarı fiyat kutu 120; toplam 720 TL.','B’de her aynı ürün çifti 1,6 etiket bedeline gelir.'],['B toplamı 1,6 × 300 + 1,6 × 120 = 480 + 192 = 672 TL.','A’dan 720 − 672 = 48 TL ucuz; D. B kampanyasında iki kişi birlikte alınca aynı tür ikililer oluşur.'],'B’nin%40 indirimini çanta ve kutudan oluşan farklı ürün çiftine uygulamak veya her iki ürünü%40 indirimli saymak.','Kampanya kapsamı','Aynı etiket fiyatında indirim oranı kadar hangi ürünün indirildiği de toplamı belirler.','İki eş ürün 100 er TL, ikinci%40 indirimli. Toplam ödeme kaç TL?',['120','140','150','160','180'],3,'İlk 100, ikinci 60; toplam 160.');
M(171,'Parkurun beşte biri ve dörtte dördü','Hareket problemleri',54,'AB’nin bir eş parça 60 saniyelik yüksek tempoya, kalan dört parçanın 320 saniyelik düşük tempoya karşılık gelmesini kullanır.',['Dairesel parkur beş eş uzunluk parçasıdır.','Yüksek tempoda bir parça 60, düşük tempoda bir parça 320/4 = 80 saniyedir.'],['Tüm parkur yüksek tempoda 5 × 60 = 300 saniye.','Düşük tempoda 5 × 80 = 400 saniye. Fark 100 saniye; C. İstenen gerçek karma turun 380 saniyesi değildir.'],'320 ile 60’ı doğrudan çıkarıp bütün tur farkı sanmak; iki süre farklı yol uzunluklarına aittir.','Orantılı süre','Sabit hızda aynı tempodaki süre yol uzunluğuyla doğru orantılıdır; önce ortak bir parça karşılaştırılır.','Parkurun 1/4’ü hızlı tempoda 30, kalan 3/4’ü yavaşta 120 saniye. Tam tur süre farkı kaçtır?',['20','30','40','50','60'],2,'Hızlı tam 120, yavaş tam 160; fark 40 saniye.');
M(172,'Sergide satılan, kalan ve yeni tablolar','Kesir problemleri',48,'Her sergide%60 satıştan sonra kalan%40’a aynı miktarda yeni eser eklenmesinin sonraki sergiyi öncekinin%80’i yapmasını ölçer.',['Her sergi sonunda 2/5 kalır; bu kadar yeni tablo eklenince sonraki sergide 4/5 önceki toplam bulunur.','Üçüncü sergi ilk toplamın(4/5)² si, satışı bunun 3/5 idir.'],['(3/5)(4/5)²N = 96;48N/125 = 96.','N = 250 tablo; D. Üçüncü sergide 160 sergilenip 96 satılması sonucu doğrular.'],'Yeni tabloları ilk sergi sayısı kadar sanmak veya 96’yı üçüncü serginin tümü kabul etmek.','Geometrik süreç','Tekrarlanan aynı kalan–ekleme kuralı sergi toplamlarını sabit 4/5 katsayılı diziye dönüştürür.','İlk sergi 200, her yeni sergi öncekinden%20 az. İkinci sergide kaç tablo vardır?',['120','140','150','160','180'],3,'200 × 0,8 = 160.');
M(173,'Bilye grup sayılarıyla ters basamak','Sayı basamakları',16,'Aynı bilye toplamının 3·AB ve 8·BA ifadelerini eşitleyip sayının bölenleri arasından yeni grup sayısını seçer.',['3 erli grup sayısı AB ise toplam 3(10A+B) dir.','8 erli grup sayısı BA ise aynı toplam 8(10B+A) dır.'],['30A+3B = 80B+8A;22A = 77B,2A = 7B. Rakam çözümü A = 7, B = 2.','Toplam 216 bilye; seçeneklerde 216’yı tam bölen 54’tür, her grup 4 bilye içerir. C.'],'AB’yi toplam bilye sayısı sanmak veya yeni grup sayısını 216’nın katı olarak aramak.','Bölen ve grup sayısı','Sabit toplamda eş grupların sayısı da bir bölen olmalıdır; grup boyuyla grup sayısı birbirine ters orantılıdır.','180 bilye 45 eş gruba ayrılırsa grupta kaç bilye olur?',['3','4','5','6','9'],1,'180/45 = 4.');
M(174,'Restoran yaşıyla iki doğum yılı','Yaş problemleri',49,'1949’da 11 yaşında olan dede ve restoran 40 yıllıkken doğan torunun doğum yıllarını ayrı bulur.',['Dede doğumu 1949 − 11 = 1938’dir.','Torun doğumu 1949 + 40 = 1989’dur; 40 torunun yaşı değil restoranın o tarihteki yaşıdır.'],['2022’de dede 2022 − 1938 = 84, torun 2022 − 1989 = 33 yaşındadır.','Yaş toplamı 84 + 33 = 117; E. İki tarihteki ifadeler aynı referans yılına taşınmalıdır.'],'Torunu 2022’de 40 yaşında saymak veya dede doğumuna 1949 + 11 yazarak zamanı ters çevirmek.','Takvim aritmetiği','Bir olayın kuruluş yaşı olay yılını, bir kişinin o yıldaki yaşı doğum yılını belirler; zincir aynı yöntemle çözülür.','1950’de 20 yaşında biri 2025’te kaç yaşındadır?',['75','85','90','95','100'],3,'75 yıl geçmiştir; 20 + 75 = 95.');
M(175,'Ulaşım türlerinde kişi ve ücret oranı','Oran orantı',46,'Otobüs 108 kişisinin uçak grubunun 6 katı olmasını, uçak ve tren toplam gelirlerinin eşitliğiyle birleştirir.',['Uçak kişi sayısı 108/6 = 18’dir.','Uçak toplam 18 × 750 = 13500 TL; tren toplamı da bu kadardır.'],['Tren bileti 300 TL olduğundan trenle 13500/300 = 45 kişi gider.','Toplam 108 + 18 + 45 = 171 kişi; B. Otobüs bilet fiyatı toplam kişi sayısı için gerekli değildir.'],'Toplam ücret eşitliğinden tren ve uçak kişi sayısını eşit sanmak; birim bilet fiyatları farklıdır.','Ters fiyat–kişi oranı','Eş gelirde pahalı bilet daha az kişiyle aynı toplamı sağlar; fiyat oranı kişi sayısına ters yansır.','Biletleri 200 ve 500 TL iki grubun geliri eşit, pahalı grubunda 12 kişi var. Ucuz grubunda kaç kişi?',['20','24','25','30','36'],3,'12 × 500/200 = 30 kişi.');
M(176,'Pasta grafiğinin eksik yüzdesi','Yüzde problemleri',51,'Etiketlenmiş dört harcama yüzdesini toplayıp bütün%100’den çıkararak eğitim simgeli dilimi bulur.',['Daire grafiğinin tüm dilimleri bütün harcamayı,%100’ü gösterir.','Bilinenler%15,6,%8,2,%12,8,%43,4’tür.'],['Toplam 15,6 + 8,2 + 12,8 + 43,4 = 80.','Kalan eğitim yüzdesi 100 − 80 = %20; E. Simgeli dilimin görsel açısını yaklaşık ölçmek gerekmez.'],'Dilim sayısına bakıp her biri%20 sanmak; sonuç burada tesadüfen 20 olsa da dilimler eş değildir.','Bütünleme','Eksik kategori, bilinen ayrık kategorilerin bütünden farkıdır; verilen ondalık yüzdeler kesin hesap sağlar.','Dört kategorinin oranı%18,%27,%35 ve bilinmeyen. Sonuncu yüzde kaçtır?',['15','18','20','22','25'],2,'18 + 27 + 35 = 80; 100 − 80 = 20.');
M(177,'Artan sonra azalan yürüyüş dizisi','Ardışık sayılar',15,'İlk 15 gün 1 er dakika artışla sonraki 15 gün 1 er dakika azalışı ayrı aritmetik diziler olarak toplar.',['İlk gün x ise 15. gün x + 14’tür.','16. gün x + 13 başlayıp 30. gün x − 1 olur; ikinci bölümün zirvesi tekrar sayılmaz.'],['İlk toplam 15x + 105, ikinci 15x + 90; genel toplam 30x + 195.','30x + 195 = 1395; 30x = 1200, x = 40 dakika, C. İlk ve son gün süreleri eşit değildir.'],'16. gün de x + 14 yazarak tepeyi iki kez saymak veya 30. günü x yapmak.','Aritmetik toplam','Sabit artışlı dönemlerin uç ortalaması × terim sayısı yöntemi, otuz günü tek tek yazmadan toplamı verir.','İlk gün 20 dakika, beş gün 1 er artış. Bu beş gün toplamı kaçtır?',['100','105','110','115','120'],2,'20 + 21 + 22 + 23 + 24 = 110.');
M(178,'İki merdivende aynı kedi yüksekliği','Oran orantı',46,'Üçüncü ve dördüncü basamakların eş yüksekliğini 4 ve 5 basamaklı merdivenlerin toplam üst yüksekliği 124 le bağlar.',['Birinci basamak yüksekliği a, ikinci b; 3a = 4b = h.','En üstler 4a ve 5b; toplam 124 cm dir.'],['a = h/3, b = h/4; 4h/3 + 5h/4 = 31h/12 = 124.','h = 48 cm; C. Basamak sayısı 4 ve 5 olmasına rağmen kediler en üstlerde değildir.'],'Üst yüksekliklerini doğrudan eşitlemek veya kedi konumlarını 3/4 ile 4/5 oranlarında ters kullanmak.','Ortak seviye','İki farklı eş bölmeli yapı aynı ara yüksekliği ölçer; bu ortak h bütün kenarları tek değişkenle ifade eder.','3a = 4b ve 4a + 5b = 62 ise ortak 3a kaçtır?',['20','22','24','26','28'],2,'Aynı 31h/12 = 62’den h = 24.');
M(179,'Arama kaydındaki iki günlük yüzde','Yüzde problemleri',51,'İlk gün Erhan ve Ahmet yüzdelerinden kalan sabit 4 görüşmeyle toplamı bulur; bugünkü bilinmeyeni iki günün ortak oranına yerleştirir.',['Dün diğer kişilerle 1 + 1 + 2 = 4 görüşme,%40 lık kalan kısımdır.','Dünkü toplam 10; Erhan 4, Ahmet 2 görüşmedir.'],['Bugünkü toplam 2 + 1 + c + 4 + 3 + 3 = 13 + c. İki gün toplamı 23 + c.','Erhan toplamı 4 + c = 0,24(23 + c); 0,76c = 1,52, c = 2. Bugün Erhan 2 görüşme; B.'],'%24’ü yalnız bugünkü toplama uygulamak veya dünün sembol a sını bugünkü c ile eşit sanmak.','Ortak toplamın değişmesi','İki günlük oran hem yeni Erhan görüşmelerini hem yeni toplamı içerir; bilinmeyen pay ve paydada birlikte görünür.','Dün 4, bugünx görüşme, total 20 + x; oran 1/3 ise x kaçtır?',['2','3','4','5','6'],2,'(4 + x)/(20 + x) = 1/3; 12 + 3x = 20 + x, x = 4.');
M(180,'Şirket yaşlarında değişen oran','Yaş problemleri',49,'2021’de 5 kat olan sektör süresinin üç yıl sonra 4 kata düşmesini iki sürenin eşit 3 yıl artmasıyla modeller.',['2021 B süresi x, A süresi 5x.','2024 süreleri x + 3 ve 5x + 3’tür; kuruluş farkı değişmez.'],['5x + 3 = 4(x + 3); x = 9.','A şirketi 2021’de 45 yıldır çalışmaktadır; kuruluş 2021 − 45 = 1976, D. 2024 − 48’de aynı yılı verir.'],'Üç yılda süre oranının sabit kalacağını sanmak veya yalnız genç şirketin süresine 3 eklemek.','Aynı artış, farklı oran','Yaş farkı sabitken oran zamanla 1’e yaklaşır; iki tarihteki oran ortak başlangıç süresini belirler.','Bugün A, B’nin 3 katı,5 yıl sonra 2 katı. B bugün kaç yaşında?',['3','4','5','6','10'],2,'3x + 5 = 2(x + 5); x = 5.');
M(181,'Sınav puanından doğru soru kümeleri','Sayı problemleri',47,'1,2,3 puanlı soruların alt küme toplamlarını kullanıp aynı 3 puanın iki farklı doğru soru deseninden gelebileceğini ayırır.',['6 puan üç soru,5 puan 2 + 3,4 puan 1 + 3 ile oluşur.','19 öğrenciden 6 sı 3,5 i6 puan; geriye 8 kişi kalır ve 4 ile 5 puan alanlar eşit olduğundan dörderdir.'],['1 puanlı soruyu bilen 11 kişinin 5 i6 puanlı,4 ü4 puanlı; geriye 3 puanını 1 + 2 ile alan 2 kişi kalır.','Bu iki kişi 3 puanlı soruyu bilmez; diğer 17 kişi bilir. E. 3 puan alanların hepsi aynı soruyu çözmemiştir.'],'Toplam puanı soru numarası sanmak veya 3 puanın yalnız 3 puanlı sorudan gelebileceğini düşünmek.','Alt küme toplamı','Aynı toplam farklı bileşimlerle oluşabilir; bir sorunun çözülme sayısı bu belirsiz bileşimi belirler.','1,2,4 puanlı üç soruda toplam 5 alan öğrenci hangi soruları çözmüştür?',['Yalnız 4','1 ve 2','1 ve 4','2 ve 4','Üçü'],2,'5 = 1 + 4; başka uygun alt küme yoktur.');
M(182,'İndeks aralığından boyun karesi','Oran orantı',46,'30 yaş için tablodaki 20–25 indeks sınırlarını seçip iki ideal ağırlık farkını 5h² olarak yazar.',['VKI = ağırlık/h² olduğundan ağırlık = VKI·h².','25–35 yaş aralığında ideal alt 20, üst 25’tir.'],['Ağırlık farkı(25 − 20)h² = 12,8; 5h² = 12,8.','h² = 2,56, h = 1,60 m; C. Pozitif boy seçilir ve kilogram farkı doğrudan boy farkı değildir.'],'Tablodaki 19–24 yaş grubunu kullanmak veya indeksi boyla çarparken kareyi unutmak.','Tablo ve formül birlikte','Yaş satırı doğru katsayı farkını verir; sonra formülün ters çevrilmesi fiziksel uzunluğu belirler.','İndeks alt 20 üst 24, boy 1,5 m ise ideal ağırlık farkı kaç kg?',['6','8','9','10','12'],2,'Fark 4 × 1,5² = 4 × 2,25 = 9 kg.');
M(183,'Şişe sayısı ile toplam kütle farklıdır','Oran orantı',45,'Cam/plastik adet oranını toplam kütle oranından ayırarak tek şişelerin kütle oranını bulur.',['Cam sayısı 2k, plastik 3k alınabilir.','Cam toplam/plastik toplam = (2k·c)/(3k·p) = 8/5’tir.'],['2c/(3p) = 8/5; 10c = 24p, c/p = 12/5.','İstenen plastik/cam ters oranıdır; p/c = 5/12, A. Büyük toplam kütle daha büyük adet anlamına gelmez.'],'8/5’i doğrudan bir şişenin oranı sanmak veya istenen ters oran yerine 12/5 vermek.','Birim başına miktar','Toplam kütle = adet × birim kütle; adet oranı bilindiğinde toplam oranından birim oranı ayrıştırılabilir.','A adedi B’nin yarısı, total kütleleri eşit. Bir A şişesi B’nin kaç katı ağır?',['1/2','1','3/2','2','3'],3,'Yarı sayıda şişeyle eşit kütle için her biri iki kat ağır olmalıdır.');
M(184,'Karşılaşma ve hakem görevi sayımı','Sayı problemleri',47,'Her tenisçi çiftinin bir kez oynamasını 20·19/2 karşılaşmaya çevirip üç hakemlik görevleri 19 kişiye eşit dağıtır.',['20 kişinin ikili eşleşmesi 20 × 19/2 = 190 maçtır.','Her maç 3 hakem görevi üretir; aynı hakem farklı maçlarda tekrar görev alabilir.'],['Toplam görev 190 × 3 = 570.','19 hakeme eşit pay 570/19 = 30 karşılaşma; C. 20 × 19 sayımı her maçı iki kez saydığı için yarıya bölünür.'],'190 ı19’a bölüp maç başına üç hakemi unutmak veya 20 × 19’u doğrudan maç sayısı almak.','Çift sayım','Her maç iki oyuncu açısından iki kez görünür; hakem görevi ise maç sayısının üç katı ayrı bir sayımdır.','10 oyuncu birbirleriyle birer maç yapıyor. Toplam maç kaçtır?',['35','40','45','50','90'],2,'10 × 9/2 = 45.');
M(185,'İki sıralamada değişmeyen dosya dizisi','Sıralama problemleri',55,'Dosyaları boyuta göre sıralayıp tarihlerinin de artan kalacağı en uzun alt diziyi seçer; silinen sayısını minimuma indirir.',['Boyut sırası Tarih 180, Fizik 260, Kimya 280, Felsefe 400, Matematik 500, Biyoloji 730 KB.','Bu sıradaki Mart günleri 3,9,4,1,6,7’dir.'],['Artan en uzun gün alt dizisi 3,4,6,7; dört dosya tutulabilir.','Fizik 9 ve Felsefe 1 silinince boyut ve tarih sıralamaları aynı olur. Altıdan dördü kalır, en az 2 silinir; B. Beşli artan dizi bu iki terslikle mümkün değildir.'],'Ekrandaki alfabetik sırayı korumaya çalışmak; istenen boyutla tarih sıralamalarının birbirine eşit olmasıdır.','En uzun artan alt dizi','Silme sonrası iki anahtar aynı sıralamayı veriyorsa bir anahtara göre dizilen kayıtların diğer anahtarı da artmalıdır.','Boyut sırasındaki tarih günleri 2,5,3,4 ise en az kaç dosya silinmeli?',['0','1','2','3','4'],1,'5 silinince 2,3,4 artar; tek silme yeterlidir.');
M(186,'Dönük özdeş fayanslarda renk oranı','Oran orantı',46,'Aynı fayansın iki yönde yerleşiminde bir sarı şeritte 4, bir mavi şeritte 6 adet oluşmasını alan oranıyla birleştirir.',['Özdeş fayans alanları eşit olduğundan renk alan oranı renk adet oranına eşittir.','Sarı şerit sayısı s, mavi m ise toplamlar 4s ve 6m dir.'],['4s/(6m) = 3/4; 8s = 9m, dolayısıyla s = 9k, m = 8k.','Şeritler dönüşümlü olduğundan sayı farkı en fazla 1; k = 1. Toplam 4 × 9 + 6 × 8 = 84; E. Şerit genişlikleri farklı olsa da fayans alanları aynıdır.'],'Sarı/mavi şerit sayısını doğrudan 3/4 almak; her şeridin farklı fayans adedi vardır.','Alanı adetle sayma','Eş parçalı döşemede alan oranı parçaları saymaya dönüşür; alternasyon son tamsayı ölçeğini belirler.','Bir sarı şerit 3, bir mavi 5 özdeş fayans içeriyor. İkişer şeritte toplam kaç fayans vardır?',['10','12','14','16','18'],3,'2 × 3 + 2 × 5 = 16.');
M(187,'Kümülatif isabet oranının üst sınırı','Kesir problemleri',48,'Her atış sonrası kaydedilen oranın en büyük 3/4 olması koşulunu, ilk atıştan başlayarak zaman sırasıyla uygular.',['İlk atış isabetli olsa oran 1 olur; bu 3/4’ü aşar.','Altı atışta toplam 4 isabet bulunduğundan 3/4 oranı ancak dördüncü atışta 3 isabetle görülebilir.'],['İlk atış kaçmalı,2,3,4 isabetli olmalıdır; dördüncüde 3/4 olur.','Beşinci isabet olsa 4/5 üst sınırı aşar; beşinci kaçar, altıncı isabet eder. Kaçan 1 ve 5; B.'],'Yalnız son 4/6 oranına bakmak; en büyük oran bütün ara kayıtları sınırlar.','Ön ek koşulları','Toplam sonuç aynı kalsa da olay sırası ara oranları değiştirir; her ön ek ayrı denetlenmelidir.','İlk üç atışta 2 isabet var, oran hiçbir anda 2/3’ü aşmamış. İlk atış ne olmalıdır?',['İsabet','Kaçış','Kesin belirlenemez','Yarı isabet','Atış yok'],1,'İlk isabet oran 1 yapar ve 2/3’ü aşar; ilk atış kaçmalıdır.');
M(188,'Yazıcı yüzdeleri birbirinin içindedir','Yüzde problemleri',51,'Bilgisayarın gönderme yüzdesiyle yazıcının gelenlerin basılan yüzdesini çarpar; ek 39 yaprağı iki toplam çıktı arasındaki fark yapar.',['İlk basılan 0,20 × 0,60N = 0,12N sayfadır.','İki ekran%80 olduğunda basılan 0,80 × 0,80N = 0,64N dir.'],['Sonradan eklenen 39 yaprak 0,64N−0,12N = 0,52N farkına eşittir.','N = 39/0,52 = 75 sayfa; C. Yazıcıdaki%60 başlangıç toplamının değil gönderilen sayfaların yüzdesidir.'],'%20 ile%60’ı toplamak veya%80’i doğrudan toplam sayfanın basılan oranı saymak.','İç içe yüzde','Bir alt kümenin yüzdesi tekrar yüzdelendirildiğinde bütündeki oran çarpımdır; bu ayrım iki ekranın rolünü açıklar.','100 sayfanın%40’ı gönderildi, gönderilenin%75’i basıldı. Kaç sayfa basıldı?',['25','30','35','40','75'],1,'100 × 0,4 × 0,75 = 30.');
M(189,'Grup büyüklüğünün grupta bulunması','Sayı problemleri',47,'1–8 toplamını ikiye ayırırken eşit toplam 18 ve her grupta kendi eleman sayısının bulunması koşullarını birlikte kullanır.',['Toplam 36 olduğundan iki grup 18 er toplar.','Dört–dört bölünmede iki grubun da 4 içermesi gerekir; tek 4 olduğundan mümkün değildir.'],['Gruplar 3 ve 5 kişilik olmalıdır; üçlü grup 3’ü, beşli 5’i içerir.','Üçlüde 3 dışındaki iki rakam toplam 15 olmalı; 7 ve 8.7 ile aynı grup 3’tür; B. İki–altı bölünmede ikili 18’e ulaşamaz.'],'Yalnız toplam 18 olan herhangi grubu seçmek; grup büyüklüğünü temsil eden rakamın üyeliği ek koşuldur.','Sayının iki rolü','Rakamlar hem toplanan değer hem küme eleman sayısını temsil edebilir; bu öz referanslı koşul dağılımı zorunlu kılar.','1–6 toplamı kaçtır ve iki eş toplamlı gruba ayrılabilir mi?',['18, evet','20, evet','21, hayır','22, evet','24, hayır'],2,'Toplam 21 tek olduğundan iki eş tamsayı toplamı oluşturulamaz.');
M(190,'Günlükte iki kardeşin yaş farkı','Yaş problemleri',49,'Kardeşinin doğduğu yıl 5 yaşında okula başlayan Ayşe nin, kardeşi 6 yaşında okula başlarken 11 yaşında olduğunu çıkarır.',['Ayşe ile kardeş arasında 5 yaş vardır.','Günlükte kardeş 6 yaşında olduğundan Ayşe 11 yaşındadır.'],['2020 deki yaşı bunun 3 katı 33; günlükten 22 yıl geçmiştir.','Yazım yılı 2020 − 22 = 1998; E. Günlükteki 5 Ayşe nin yazıyı yazdığı yaş değil önceki okula başlama yaşıdır.'],'5 veya 6’yı Ayşe nin o günkü yaşı sanmak; doğum ve okula başlama olayları ayrı tarihlerdedir.','Yaş farkı korunumu','Kardeşlerin sabit farkı geçmişteki olaydan çıkarılır; aynı fark sonraki tarihteki iki yaşı bağlar.','Abla kardeş doğduğunda 4 yaşında. Kardeş 7 yaşındayken abla kaçtır?',['9','10','11','12','13'],2,'Yaş farkı 4; 7 + 4 = 11.');
M(191,'Canlı konumla şehir koordinatları','Hareket problemleri',54,'Sabit 90 km/h hızı 1,5 km/dakikaya çevirip orta nokta kayıtlarından B, C, D konumlarını sırayla bulur.',['A, 0 km ve E, 300 km konumuna yerleştirilir; konum = 1,5t dir.','Bir orta nokta koordinatı iki uç koordinatının aritmetik ortalamasıdır.'],['10 dakikada 15, AB ortası; B = 30.40 dakikada 60, BC ortası; C = 90.','140 dakikada 210, DE ortası; D + 300 = 420, D = 120. CD = 120 − 90 = 30 km; A.'],'90 km/h ile dakika değerlerini doğrudan çarpmak veya orta nokta mesafesini şehirler arası mesafe sanmak.','Koordinatlandırma','Doğrusal yol ortak başlangıca göre sayı doğrusuna çevrilince orta nokta bilgileri doğrusal denklemler olur.','Araç 60 km/h ile 20 dakikada A–B ortasında. AB kaç km?',['20','30','40','50','60'],2,'20 dakikada 20 km gider; bu yarı yol olduğundan AB40 km.');
M(192,'İki tahminin ortak varış dakikası','Eşitsizlikler',32,'19.00 ve 19.06 mesajlarındaki 10–20 dakikalık beklemeleri mutlak saat aralıklarına çevirip kesişimin tam dakika değerlerini toplar.',['İlk tahmin 19.10–19.20 aralığını verir.','İkinci tahmin 19.16–19.26 aralığını verir; iki tahmin de doğruysa varış ortak bölgede olmalıdır.'],['Kesişim 19.16–19.20; dakika hanesi 16,17,18,19,20 olabilir.','Toplam 16 + 17 + 18 + 19 + 20 = 90; D. Mesajın yazıldığı saat her tahminin kendi başlangıcıdır.'],'İki tahmin aynı sözel aralık diye aynı varış aralığını verdiğini sanmak veya 19.04 sorusunu ikinci tahmin zamanı almak.','Aralık öteleme','Göreli süreler önce ortak saat eksenine taşınır; sonra mantıksal ve koşulu kesişimle uygulanır.','14.00’da 10–20,14.05’te 10–20 dakika sonra varış deniyor. Ortak en erken saat nedir?',['14.10','14.15','14.20','14.25','14.30'],1,'Aralıklar 14.10–20 ve 14.15–25; ortak başlangıç 14.15.');
M(193,'Ev sırasındaki renkleri çıkarımla bulmak','Rutin olmayan problemler',55,'Geçilen ev sayılarını kişinin sıra konumuna çevirip yön simetrisi altında renk alt toplamlarını karşılaştırır.',['Dokuz evde 4 ev geçen Arda ortadaki 5. evdedir; gittiği tarafı solda seçebiliriz.','Soldaki 1–4 evde 3 gri,1 pembe bulunur.'],['Burak sola gitse ilk 3 evde 1 gri olması ilk 4 teki 3 griyle çelişir; Burak 6. evden sağa gider,7–9’da 1 gri vardır.','Cem 2. evden sağa gider; 3–9’da 2 gri. Böylece 3–6’da 1 gri; 1–2 gri,5–6 pembe olur. Renkler pembe, pembe, gri; D.'],'Yalnız geçilen renk toplamlarını bütün sokağın toplamı sanmak; kendi evleri sayılmıyor ve yönler farklı olabilir.','Alt aralık farkları','İç içe ev aralıklarının renk sayıları çıkarılınca belirli küçük bölgelerin renkleri zorunlu olur.','İlk 5 evde 3 gri, ilk 3 evde 1 gri varsa 4 ve 5. evlerin rengi nedir?',['İkisi pembe','İkisi gri','Biri gri','Belirsiz','Ev yok'],1,'Son iki evde 3 − 1 = 2 gri vardır; ikisi de gri.');
M(194,'Mart ayının fazladan üç günü','Periyodik problemler',25,'31 günlük ayı dört tam hafta artı üç güne ayırıp ders toplamlarındaki fazlalığı haftalık çizelgede arar.',['Dört haftada 24 matematik,20 geometri olur.','Gerçek 26 ve 23 olduğundan fazladan üç ardışık günde 2 matematik,3 geometri bulunmalıdır.'],['Çizelgede Salı 2 geometri, Çarşamba ders yok, Perşembe 2 matematik 1 geometri içerir.','Bu üçlü tam 2 matematik 3 geometri verir; 1 Mart Salı, B. Diğer üç günlük ardışık bloklar iki toplamı birlikte tutturmaz.'],'Martı dört hafta sayıp son üç günü unutmak veya bütün dersleri tek toplam 49 olarak elemek.','Ortak periyot','Tam haftalar aynıdır; ayın haftaya göre kayması yalnız artan günlerdeki ders vektörüyle belirlenir.','30 günün haftalara bölümünden kaç tam hafta ve kaç gün artar?',['3 hafta 9 gün','4 hafta 1 gün','4 hafta 2 gün','4 hafta 3 gün','5 hafta'],2,'30 = 4 × 7 + 2.');
M(195,'Yılan sıralamada sütun sayısını bulmak','Sayı problemleri',47,'Ters yönlü komşu satırlarda aynı sütun sayı toplamının sabitliğini kullanır; 61’in altında satır bulunması belirsizliği kaldırır.',['60 ve 71 aynı sütunda,61 ve 70’de aynı sütundadır; toplam 131.','n sütunda bu toplam 2 rn + 1 biçimindedir; rn = 65.'],['n için 5,13,65 adayları düşünülebilir. 5 sütun 60 ve 61’i aynı satırda tutmaz; 65 sütunda 61 en alt satırda olur, alt komşusu yoktur.','n = 13; 61 beşinci satır 9. sütun. Alt dördüncü satırda 52’den sola değil sağa azalışla 52 − 8 = 44; B.'],'Komşu alt kutuyu doğrudan 61 − 13 almak; numaralandırma her satırda yön değiştirir.','Satır içi indeks','Sütun sayısı bilindikten sonra hangi satırın artan/azalan olduğu ve sütun indeksi birlikte kullanılmalıdır.','Alt satır 1–10 soldan sağa, üst 11–20 sağdan sola. Alt 7’nin üstündeki sayı kaçtır?',['12','13','14','15','16'],2,'Aynı sütun toplamı 21; 21 − 7 = 14.');
M(196,'Geri sayımın tarihle aynı rakamları','Zaman problemleri',47,'Gün ve saati takvim günü–ayı, dakika ve saniyeyi 2025 yılının 20–25 parçaları olarak okuyup kalan süreyi takvimde geriye taşır.',['Geri sayımda dakika 20, saniye 25; gün d ve saat ay m olmalıdır.','21 Haziran a en çok 31 gün kala olası tarih Mayıs veya Haziran içindedir.'],['Haziran olsaydı gün eşitliği d = 21 − d verip tamsayı olmaz. Mayısta d = 52 − d; d = 26 ve m = 5.','26 Mayıs 04.54.35’ten 26 gün 5 saat 20 dakika 25 saniye sonra 21 Haziran 10.15 olur. 26 gün önce Pazartesi; A.'],'20 ve 25’i saat ya da takvim günü olarak okumak; dört haneli yıl dakika–saniye birleşimidir.','Takvim–süre eşleme','Aynı rakamlar farklı alanlarda farklı birimler taşır; eşitlik hem tarih hem kalan zaman hesabını sağlamalıdır.','Cumartesiden 26 gün önce haftanın hangi günüdür?',['Pazartesi','Salı','Çarşamba','Perşembe','Cuma'],0,'26 mod 7 = 5; Cumartesiden 5 gün geri Pazartesi.');
M(197,'Sandalye dizisinde iki farklı çıkarma','Denklem sistemi',33,'Satır ve sütun kaldırırken kesişen sandalyelerin iki kez çıkarılmamasını çarpım biçimindeki kalan düzenle modeller.',['r sıra, c sütun için rc = 120.','İki sıra bir sütun sonrası(r − 2)(c − 1), bir sıra üç sütun sonrası(r − 1)(c − 3) sandalye kalır.'],['Eşitleme 2r − c − 1 = 0, c = 2r − 1 verir. r(2r − 1) = 120; pozitif çözüm r = 8, c = 15.','Kalan(8 − 2)(15 − 1) = 6 × 14 = 84 öğrenci; A. İki çıkarma yöntemi aynı kapasiteyi bırakır.'],'2c + r gibi düz çıkarıp kesişimleri geri eklememek; çarpım yöntemi kesişim hatasını baştan önler.','Dikdörtgen boyut değişimi','Satır–sütun silme dizinin iki boyutunu değiştirir; aynı kalan alan iki farklı boyut çarpımına eşitlenir.','8 × 12 sandalyeden 2 sıra 1 sütun kaldırılırsa kaç kalır?',['66','70','72','77','84'],0,'(8 − 2)(12 − 1) = 6 × 11 = 66.');
M(198,'Tuşların farklı basılma tekrarları','Kesir problemleri',48,'Bir kez, iki kez, üç kez basılan tuşları farklı karakter toplamıyla toplam 69 basış arasında ayrı sayar.',['Toplam tuş N ise bir kez N/3, iki kez kalan 2N/3’ün altıda biri N/9 tuştur.','Üç kez basılan z; farklı karakter sayısı4N/9 + z = 37’dir.'],['Basış toplamı5N/9 + 3z = 69. İlk denklemin üç katından çıkarınca 7N/9 = 42, N = 54.','37 farklı tuş kullanılmıştır; basılmayan 54 − 37 = 17, C. 69 basış 69 farklı tuş anlamına gelmez.'],'Geriye kalanların 1/6 sını tüm N’nin 1/6 sı almak veya üçlü basılan ek grubu unutmak.','Farklı nesne ve tekrar sayısı','Her tuş farklı karaktere bir kez katkı verirken toplam basışa kullanım sıklığı kadar katkı yapar.','20 farklı tuşun 8 ine bir,12 sine iki kez basılırsa toplam basış kaçtır?',['20','24','28','32','40'],3,'8 + 2 × 12 = 32 basış.');
M(199,'Kaplardaki iki farklı tüketim yüzdesi','Yüzde problemleri',51,'Özdeş kapların başlangıç doluluklarını normalize edip%16 kayıpla kalan tuzu,%4 kayıpla kalan karabibere eşitler.',['Tuz başlangıç 0,8 kap, kalan 0,8 × 0,84 = 0,672 kap miktarıdır.','Karabiber başlangıç x kap ise kalan 0,96x tir.'],['0,96x = 0,672; x = 0,7.','Başlangıç karabiberlik%70 doludur; E. Yüzde tüketimler kap kapasitesinin değil içindeki başlangıç maddesinin yüzdesidir.'],'80’den 16 puan çıkarıp 64 bulmak veya karabiberin başlangıç miktarını eşit son miktar sanmak.','Çarpımsal azalma','Farklı kayıp oranlarında aynı son miktar, başlangıçların oranını kalan katsayıların tersiyle belirler.','Bir kap%60 dolu, içindekinin%10’u kullanılıyor. Kalan kapasitenin yüzde kaçı?',['45','50','54','56','60'],2,'60 × 0,90 = %54.');
M(200,'Aidatta alan ve katın ayrı katkısı','Denklem sistemi',33,'Aidatı alan katsayısı × alan + kat katsayısı × kat olarak yazar; iki eşit oran bilgisiyle kat katsayısını ve Mert in alanını bulur.',['Aidat A·k + K·l biçiminde, k ve l ortak pozitif katsayılardır.','Can 110k + l, Levent 70k + 2l, Mert xk + 3l öder.'],['110k + l = (4/3)(70k + 2l) den l = 10k. Can aidatı 120k.','120k = (4/3)(xk + 30k); x + 30 = 90, x = 60 m², E. İki ücret katkısı tek orana indirgenmeden toplanmalıdır.'],'Aidatıyalnız metrekareyle doğru orantılı sanmak veya kat numarasını alana ekleyip ortak katsayı kullanmak.','İki değişkenli doğrusal maliyet','Farklı ölçü türleri farklı birim katsayılara sahiptir; eşitlikler bu katsayıların oranını belirler.','Aidat m² başına 2 TL, kat başına 20 TL. 60 m² üçüncü kat aidatı kaç TL?',['120','140','160','180','200'],3,'60 × 2 + 3 × 20 = 180 TL.');
M(201,'İki tablonun yılıyla anne–çocuk yaşları','Yaş problemleri',49,'2013 ve 1999 tarihlerini 2025’e göre 12 ve 26 yıl geriye taşıyıp iki konuşma cümlesini ayrı yaş denklemine çevirir.',['Bugün anne M, çocuk C yaşındaysa 2013 yaşları M − 12 ve C − 12.','1999’da annenin yaşı M − 26’dır; bu çocuğun bugünkü yaşına eşittir.'],['(M − 12) + (C − 12) = M’den C = 24.','M − 26 = 24 olduğundan M = 50; 2025 toplamı 74, E. İlk cümlede toplam annenin o yılki değil şimdiki yaşına eşitlenir.'],'Her iki cümleyi aynı tarihteki yaşlara eşitlemek veya 2013 toplamından anneyi çıkarırken 12 yıllık iki katkıyı unutmak.','Zamana göre öteleme','İki kişinin toplam yaşı her yılda 2 artar; tek kişinin yaşı her yılda 1 artar, bilanço bu farkı kullanır.','On yıl önce anne ile çocuğun yaş toplamı annenin bugünkü yaşına eşit. Çocuk bugün kaç yaşında?',['10','15','20','25','30'],2,'(M − 10) + (C − 10) = M; C = 20.');
M(202,'İlçeden tekrarlı geçiş ve uçta bekleme','Hareket problemleri',54,'A–B ve B–C yolculuk sürelerini ayrı değişkenlerle yazıp her uçtaki 30 dakikalık molayı doğru geçiş aralıklarına ekler.',['A–B süresi x, B–C süresi y dakika olsun.','08.00’den ikinci B geçişine x + 2y + 30 = 210; üçüncüye 3x + 2y + 60 = 400 dakika geçer.'],['Denklemleri çıkarınca 2x + 30 = 190, x = 80; ilkinden y = 50.','Üçüncüden dördüncü B’ye 2y + 30 = 130 dakika. 14.40 + 130 = 16.50; A. B’de mola verilmez.'],'Her B geçişi arasındaki süreyi eşit sanmak; araç bir sefer C, diğerinde A ucuna gidip döner.','İki periyotlu gidiş–dönüş','Ara nokta geçiş aralıkları uç uzaklıklarına bağlı dönüşümlü iki değer alır; molalar da ilgili uca eklenir.','B–C yolculuğu 40 dakika, uçta 20 dakika mola. B’den C’ye gidip yeniden B’ye dönüş kaç dakika?',['60','80','90','100','120'],3,'40 + 20 + 40 = 100 dakika.');
M(203,'Günlük sürüş dışı sürenin oranı','Hareket problemleri',54,'Her günü 24 saat olarak alıp sürülmeyen/sürülen oranının 2–3 arasında olmasından 6–8 saatlik sürüş aralığı çıkarır.',['Sürüş t ise sürüş dışı 24 − t saat.','2 < (24 − t)/t < 3 koşulu 6 < t < 8 verir; iki günde hız aynıdır.'],['88 km için 11 < v < 44/3; 108 km için 13,5 < v < 18.','Kesişim 13,5 < v < 14,666...; seçenek 14 km/h, C. İki günün sürüş süreleri eşit olmak zorunda değildir.'],'88 ile 108’in ortalamasını 24’e bölmek; günlerin tamamı sürüşe ayrılmamıştır.','Aralıkların ortak hızda kesişimi','Her gün kendi mesafesiyle hız için bir aralık oluşturur; ortak sabit hız iki aralığı aynı anda sağlamalıdır.','Bir günde sürülmeyen süre sürülenin 3 katıysa kaç saat sürülmüştür?',['4','5','6','8','12'],2,'Toplam 4t = 24; t = 6 saat.');
M(204,'Cumartesi–pazar tarih toplamları','Periyodik problemler',25,'Ayın aynı sayıdaki hafta sonu günlerinin toplam farkının yalnız 4 veya 5 olacağını görüp bir günün beş kez gerçekleştiği sınır durumunu arar.',['Eş sayıda Cumartesi–Pazar varsa ardışık tarihler nedeniyle fark 4 veya 5’tir.','27 fark için ayın 31 günü ve Cumartesilerin 3,10,17,24,31 olması uygundur.'],['Bu Cumartesiler toplam 85; Pazarlar 4,11,18,25 toplam 58. Fark 27.','Ayın 3’ü Cumartesi ise 1’i Perşembe; D. Başlangıçtaki haftanın kayması ay sonundaki fazladan günü belirler.'],'Her ay dört hafta sonu olduğunu kabul etmek veya tarih toplamını hafta sonu gün sayısı sanmak.','Takvimde uç etkisi','Tam haftalar benzer katkı yapar; 27 gibi büyük fark ayın başı–sonunda eşleşmeyen bir tarihten doğar.','Ayın 3’ü Cumartesi ise 1’i hangi gündür?',['Salı','Çarşamba','Perşembe','Cuma','Pazar'],2,'İki gün geri Perşembe.');
M(205,'Bozuk yazıcının satır periyodu','Periyodik problemler',25,'Sekiz harfli EBEDİYEN dizisinin her 30 harfte yeni satıra geçip yalnız ilk 28 harfin basılmasını satır başlangıç kaymalarıyla sayar.',['Kelime 8 harfli ve 3 E içerir.','30 mod 8 = 6 olduğundan satır başlangıcı dört satırda tekrar eder; boş bırakılan iki harf de bu kaymaya bağlıdır.'],['İlk dört basılmış satırdaki E sayıları 11,11,10,10 biçimindedir; toplam 42.','22 satır 5 tam dörtleme ve iki ek satırdır; 5 × 42 + 11 + 11 = 232 E, A. Her satır aynı harfle başlamaz.'],'28 × 22 harfi kesintisiz bir metin sanmak; atlanmış iki karakter dizinin ilerlemesini durdurmaz.','Birleşik periyot','Kelime uzunluğu 8 ile satır uzunluğu 30’un ortak durumu dört satırda yinelenir; tek tek 660 konumu saymaya gerek kalmaz.','Dört satırda E sayısı 5,6,5,6 diye tekrarlıyor. 10 satırda toplam kaç E vardır?',['50','52','54','55','56'],3,'İki tam döngü 44, iki ek satır 11; toplam 55.');
M(206,'Paket alışverişinde ortak son toplam','Denklem sistemi',33,'Hayri 15, Kâmil 20, Mert 19 top toplamlarının eşit son 18’e ulaşmasını verilen–alınan paket farklarıyla modeller.',['Toplam 54 top üç kişide eşitlenince kişi başı 18 olur.','Hayri x verir, Mert ten z alır; Kâmil y verir; z − x = 3, y − x = 2’dir.'],['Dolayısıyla y = x + 2, z = x + 3. x Hayri nin 1–5 paketlerinden seçilir.','x = 4 için y = 6 Kâmil de, z = 7 Mert te vardır; öteki x lerden en az bir paket yoktur. Hayri 4 top verir; D.'],'Paketin üstündeki sayıyı paket sıra numarası sanmak veya toplam 54 yerine paket sayısı 15’i eşitlemek.','Döngüsel aktarım','Her kişinin stok değişimi gelen eksi gidenle ölçülür; ortak son değer bütün sistem toplamından bulunur.','Bir kişinin 15 topu var,4 verip 7 alıyor. Son top sayısı kaçtır?',['16','17','18','19','20'],2,'15 − 4 + 7 = 18.');
M(207,'Koridor çıkışında öndeki oda toplamları','Rutin olmayan problemler',55,'Dörder odalı iki tarafta 20 toplamının ancak üç oda numarası 5,7,8 ile oluşmasını kullanıp iki kişinin kendi numaralarının olası toplamlarını sınar.',['Bir çıkışa giderken en çok 3 başka oda geçilebilir.','20 yapan farklı üç rakam yalnız 5 + 7 + 8; 20’yi bulan kişi o taraftaki en iç odadadır.'],['Kendi numarası x,1,2,3,4,6’dan biridir. 5 bulan kişi ya aynı tarafta 5’ten sonra 7/8’dir ya diğer tarafta 1 + 4 veya 2 + 3 çiftini geçer.','Bu durumlarda toplam 5,7,8,9 mümkünken 6 mümkün değildir; B. Örneğin 6 için 2 ve 4 adayları diğer tarafta 5 toplamını kuramaz.'],'Geçilen odaların toplamına kişinin kendi oda numarasını da eklemek; metin açıkça kendi odasını dışlar.','Tamsayı alt küme kısıtı','Koridordaki en fazla üç oda sınırı, toplamı sağlayan rakam alt kümelerini çok daraltır.','Farklı 1–8 rakamlarından üç tanesinin toplamı 20 ise rakamlar hangileridir?',['4,7,8','5,6,8','5,7,8','3,8,9','6,7,8'],2,'Yalnız 5 + 7 + 8 = 20; diğer geçerli üçlüler 19 veya 21 verir.');
M(208,'Her önermesinin değili ve tablo şekli','Bileşik önermeler',58,'(p∨q)′∧r doğru koşulunda p ve q nun yanlış, r nin doğru olmasını, her niceleyicisinin anlamıyla resimlere uygular.',['De Morgan ile(p∨q)′ = p′∧q′.','p yanlış demek en az bir tablo düz, q yanlış demek en az bir tablo kişisiz; r doğru bütün tablolar dikdörtgendir.'],['A seçeneğinde iki tablo düz, biri ters; hepsi ters değildir.','Portakal tablosu kişisizdir ve üç şekil de dikdörtgendir. p = 0, q = 0, r = 1; A. C’de üçgenler r yi bozar, D’de hepsi ters olduğundan p doğrudur.'],'Her tablo ters değildir cümlesini hiçbir tablo ters değildir şeklinde aşırı güçlü okumak veya r ye olmayan değili eklemek.','Niceleyicinin değili','Bir evrensel önermeyi yanlışlamak tek karşı örnekle mümkündür; diğer tabloların nasıl olduğu serbest kalabilir.','p = 0, q = 0, r = 1 ise(p∨q)′∧r nedir?',['0','1','p','q','Belirsiz'],1,'p∨q = 0, değili 1; 1∧1 = 1.');
M(209,'Mantıksal doğrulukla üç yol ayrımı','Bileşik önermeler',58,'p′∧(q∧r) doğru bilgisini sırasıyla sağ, çiçekçi bulunan kol, sağ kararlarına çevirip şemadaki yolu takip eder.',['Ve bağlacının doğru olması bütün bileşenlerin doğru olmasını gerektirir.','p′ doğruysa ilk ayrımda sol değil sağ; p yanlış olur.'],['İlk ayrımda sağ kola geçilir. İkinci ayrımda çiçekçi bulunan iç kol seçilir.','Üçüncü ayrımda sağ yol izlenince Derya ya ulaşılır; D. İkinci ayrımda sağ/sol ifadesi değil işaretli dükkân koşulu verilmiştir.'],'p′ yi p ile aynı davranış gibi okumak veya yol ayrımlarını şeklin üstünden aşağı doğru saymak.','Durumdan eyleme dönüşüm','Mantık formülü önermelerin doğruluk değerlerini belirler; harita her değeri somut yön seçimine çevirir.','p′∧q doğruysa p ve q sırasıyla nedir?',['1,1','1,0','0,1','0,0','Belirsiz'],2,'p′ = 1 olduğundan p = 0, q = 1.');
M(210,'Yanlış koşullu önermeden ölçüleri bulmak','Koşullu önerme',60,'53 yaş nedeniyle r nin yanlışlığını kullanıp(p⇒q′)∧r′ ifadesinin yanlış olmasını koşullunun yanlışlık durumuna indirger.',['r yanlış olduğundan r′ doğrudur.','p⇒q′ ancak p doğru, q′ yanlışken yanlıştır; dolayısıyla p ve q doğrudur.'],['Kilo 60’tan büyük, boy 164–170 cm aralığında olmalıdır.','166 cm–62 kg bu iki koşulu birlikte sağlar; C. Yaş bilgisinin r yi sabitlemesi diğer ölçüleri zorunlu kılar.'],'Koşullu önermeyi yalnız öncül doğruysa doğru sanmak veya q′ yerine q yu sonuçta yanlış yapmak.','Yanlışlık tablosu','Bir koşullunun tek yanlış satırı, eksik iki ölçünün aralıklarını doğrudan verir.','p⇒q yanlışsa p, q hangi değerlerdedir?',['0,0','0,1','1,0','1,1','Her ikisi belirsiz'],2,'Doğru öncülden yanlış sonuca gidilen 1⇒0 satırı yanlıştır.');
M(211,'Ücretli ve ücretsiz seçimlerde önerme kapsamı','Bileşik önermeler',58,'p′∧r ve p∨q nun birlikte doğruluğundan üç hizmet seçiminin ücret durumlarını ayrı belirler.',['p′∧r doğruysa p yanlış, r doğrudur.','p∨q doğru, p yanlış olduğunda q doğru olmak zorundadır.'],['Koltuk için ücret ödenmez; standart a seçilir. q bagaj için ücret ödenmediğini söyler; doğru olduğundan a.','r yemek ücretini ödediğini söyler; b yemek seçilir. Sıra a–a–b; E. q nun sözel tanımında zaten değil vardır.'],'q doğruyu ücretli bagaj sanmak; önermenin içindeki olumsuzlukla mantıksal değer farklı düzeylerdir.','Doğruluk ve sözel olumsuzluk','Bir değil içeren cümlenin doğru olması ilgili olayın gerçekleşmediğini söyler; etiketler dikkatle eşlenmelidir.','p yanlış, q doğru ise p∨q ve p∧q sırasıyla nedir?',['0,0','0,1','1,0','1,1','Belirsiz'],2,'Veya için bir doğru yeterli, ve için ikisi de doğru gerekir.');
M(212,'İç içe koşullunun yanlış olduğu tarih','Koşullu önerme',60,'Dış koşullunun doğru öncül–yanlış sonuç gerektirmesini önce r⇒q ya sonra p⇒q ya uygular.',['(p⇒q)⇒(r⇒q) yanlışsa r⇒q yanlış olmalıdır.','Bu r doğru, q yanlış demektir; öncül p⇒q doğru kalacağı için p yanlış olmalıdır.'],['Beyza 2000 yılında, Eylül dışında ve ayın 1’i olmayan günde doğmuştur.','Seçenek 4 Aralık 2000; A. 1 Aralık 2000 yılı ve ayı sağlasa da p yi doğru yaptığı için dış öncülü yanlış yapar.'],'Yalnız sonucu yanlış yapıp dış koşullunun öncülünün de doğru olması gerektiğini unutmak.','Katmanlı doğruluk','İç içe ifadeler dıştan içe çözülür; her yanlış koşullu iki alt doğruluğu sabitler.','r⇒q yanlış, r2001’de doğdu, q Ocak ayında doğdu ise ne kesindir?',['2001 değil','Ocakta','2001’de ve Ocak dışında','İkisi yanlış','Belirlenemez'],2,'r doğru, q yanlış olmalıdır.');
M(213,'Koşullu önermeden otomobil sırası','Koşullu önerme',60,'Yanlış dış koşulludan r doğru, p yanlış, q doğru değerlerini çıkarıp beş konumun uç ve mesafe kısıtlarını çözer.',['r doğruysa C ile D arasında 3 araba bulunur; C, D uçlardadır.','p yanlış, q doğru:AB arasında tam 1 araba yok, BC arasında tam 2 araba vardır.'],['Simetriyle C’yi 1, D’yi 5 al; B, C’den 3 konum uzakta 4 tedir.','A kalan 2 veya 3 tedir; 2 olursa B ile arasında 1 araba olur, p doğru çıkar. A, 3. konumda; E, 2. konumda kalır. Ortadaki A; A.'],'Arasında iki araba ifadesini konum farkı 2 sanmak; araya giren sayıya 1 eklenir.','Mantık ve diziliş','Önce doğruluk tablosu ilişkileri seçer, sonra bu ilişkiler konum farklarıyla sonlu yerleşime dönüşür.','Beş konumda iki araba arasında 3 araba varsa hangi konumlardadır?',['1 ve 4','2 ve 5','1 ve 5','2 ve 4','3 ve 5'],2,'Arada 3 konum olması fark 4 gerektirir; uçlar 1 ve 5.');
M(214,'İki harf koşulundan yalnız biri','Kümelerde fark',67,'B içindeki A ve N’nin ortak olmayan iki boyalı lobunu, beş harfli isimlerde başlama–bitme koşulunun özel veyası olarak okur.',['Bütün boyalı alan beş harfli B kümesindedir.','A ile N kesişimi boyasızdır; A ile başlayan veya N ile bitenlerden yalnız bir koşulu sağlayanlar alınır.'],['AHMET5 harfli, A ile başlar, N ile bitmez; BEREN ve KENAN 5 harfli, N ile biter, A ile başlamaz.','AYSUN iki koşulu da sağlar ve dışlanır; AÇELYA, NERMİN6 harflidir. Üç isim; C.'],'Birleşim gibi okuyup AYSUN’u dahil etmek veya harf sayısı şartını yalnız A tarafına uygulamak.','Simetrik fark','(A\N)∪(N\A) iki koşuldan tam birini sağlar; B ile kesişim uzunluk filtresini ekler.','Beş harfli, A ile başlayıp N ile biten AYLIN boyalı simetrik farkta mıdır?',['Evet','Hayır, iki koşulu da sağlar','Harf yok','Yalnız N nedeniyle','Kesin değil'],1,'Ortak bölge boyasız olduğundan iki koşulu birden sağlayan isim alınmaz.');
M(215,'Altı katı olup on iki katı olmayanlar','Kümelerde fark',67,'2 ve 3 ile bölünenlerin kesişiminden 12 katlarını çıkaran boyalı bölgeyi sayısal bölünebilme koşullarına çevirir.',['A∩B,2 ve 3’ün EKOK u6’nın katlarıdır.','C, 12’nin katlarıdır ve 6 katlarının alt kümesidir; boya(A∩B)\C dir.'],['18 ve 42,6’ya tam bölünür ama 12’ye bölünmez.','24 ise 12 katı olduğundan merkezdeki boyasız C alanındadır. I ve III; D. Yalnız 2 veya yalnız 3 katı olmak yeterli değildir.'],'C’yi A veya B’den bağımsız üçüncü küme sanmak; 12 katı sayı iki koşulu da zaten sağlar.','Bölünebilme ile alt küme','Bir sayının 12 katı olması 6 katı olmasını zorunlu kılar; Venn iç içeliği bu mantıksal gerektirmeyi gösterir.','Hangisi 6’nın katı olup 12’nin katı değildir?',['12','24','30','36','48'],2,'30/6 = 5,30/12 tamsayı değildir.');
M(216,'Telefon rakamlarında küme farkı','Kümelerde fark',67,'Görünen rakamları ve farklı eleman sayılarını kullanarak tekrarların küme büyüklüğüne katkı vermediğini uygular.',['B’nin 6 elemanı, ortak 0,1,4,5,6 ve görünen 9 ile tamamen belirlenir.','A’nın ortaklara ek görünen 2,3,7 si vardır; 9 eleman için bir rakam daha gerekir.'],['A’da 9 olamaz, çünkü 9 B’de olup ortak listede değildir. Kalan mümkün rakam 8’dir.','A\B = {2,3,7,8}; toplam 20, B. Telefonun 11 hanesi 9 farklı rakam demektir,11 eleman değil.'],'Aynı 5’in birkaç kez görünmesini farklı küme elemanları saymak veya saklı her haneyi yeni rakam sanmak.','Küme ile dizi farkı','Telefon numarası sıralı ve tekrarlı bir dizi olsa da oluşturulan küme yalnız farklı rakamları tutar.','Rakam kümesi{0,2,5,8} olan bir numarada beş kez 5 geçerse küme kaç elemanlıdır?',['4','5','6','8','9'],0,'Tekrar sayısı küme eleman sayısını değiştirmez; dört farklı rakam vardır.');
M(217,'Ortak harflerin zorunlu kapasitesi','Alt küme',65,'İki kelimenin kesişimde yazılabilmesiyle ortakta zorunlu altı harfi belirleyip 9 elemanlı A’nın alabileceği yeni harf sayısını sınırlar.',['Akademisyen kelimesinin 9 farklı harfi vardır; tek başına 9 luk kesişim olsa A = B olur, asker için r eklenemez.','Bu yüzden asker veressam kesişimde; ortak zorunlu harfler{a, s, k, e, r, m} dir.'],['A en fazla üç ek harf taşıyabilir.','Sanatçı için ortaklara ek{n, t, ç, ı} dört harf gerekir; toplam en az 10 olur,9’a sığmaz. Kesin yazılamayan D. Diğer seçenekler en fazla üç yeni harf ister.'],'Bir kelimedeki tekrar eden harfleri ayrı eleman saymak veya A’nın 9 harfini herhangi biçimde serbest seçilebilir sanmak.','Kapasite alt sınırı','Zorunlu alt küme 6 eleman tuttuğunda kalan kapasite 3’tür; aday kelimenin yeni harf gereksinimiyle karşılaştırılır.','9 elemanlı harf kümesinde 6 harf zorunluysa en fazla kaç yeni farklı harf eklenebilir?',['2','3','4','5','6'],1,'9 − 6 = 3 yeni harf.');
M(218,'İki katına çıkarılan kümenin kesişimi','Kümelerde işlemler',66,'{2,4,8, a} ile{4,8,16,2a} nın zaten ortak 4 ve 8 ine üçüncü ortak değerin hangi yollardan eklenebileceğini sayar.',['İki küme dört elemanlı olduğundan a,2,4,8’den farklıdır.','Sabit ortaklar 4 ve 8; tam 3 kesişim için a veya 2a yeni bir ortak oluşturmalıdır.'],['a = 16 olursa 16 ortak, a = 1 olursa 2a = 2 ortak, a = 0 olursa a = 2a = 0 ortak olur.','Başka değer üçüncü ortak oluşturmaz. Toplam 16 + 1 + 0 = 17; C. Sıfır tamsayı olduğu için dışlanamaz.'],'a yı pozitif varsayıp 0’ı kaçırmak veya 2,4,8 seçip başlangıç kümesinin dört elemanlığını bozmak.','Sonlu eşitlik analizi','Ortak yeni eleman a = 16,2a = 2 veya a = 2a gibi bir eşitlikten doğar; olası eşleşmeler sistematik incelenir.','B = {1,2,4},2B = {2,4,8}. Kesişim kaç elemanlıdır?',['1','2','3','4','5'],1,'Ortak elemanlar 2 ve 4; iki eleman.');
M(219,'İsim harfleriyle gerekli ve yasak elemanlar','Kümelerde kesişim',66,'Kız isimleri kümesiyle erkek isimleri kümesinin tam verilen kesişimini sağlayacak yeni erkek isminde gerekli B, U ve yasak ortak harfleri arar.',['Mevcut AKIN ve KENAN erkek harflerinde A, E, N vardır; B ve U eksiktir.','Yeni isim B ve U eklemeli; AYLİN ile BENSU’dan başka ortak Y, L, İ, S yaratmamalıdır.'],['BURAK, B ve U içerir; R, K kız harflerine yeni ortak eleman eklemez.','BULUT L, BURAY Y ekleyerek kesişimi büyütür; diğerleri U yu sağlamaz. Uygun BURAK; E. Türkçedeki I ve İ farklı harflerdir.'],'İsimdeki bütün harflerin kesişimde bulunması gerektiğini sanmak; erkeklerde olup kızlarda olmayan R, K serbesttir.','Gerekli–yasak harf filtresi','Tam kesişim bilgisi hem bulunması gereken hem bulunmaması gereken ortak elemanları belirler.','X = {A, B, U}, mevcut Y = {A}. X∩Y’nin{A, B, U} olması için yeni Y’ye ne eklenmeli?',['Yalnız B','Yalnız U','B ve U','Yalnız A','Hiçbiri'],2,'Eksik ortakB ve U’nun ikisi de Y’de bulunmalıdır.');
M(220,'Küme toplamlarının eşitliğinde ortakları silmek','Kümelerde fark',67,'Kesişimdeki 1,9 ve ayrık bölgelerde zorunlu 3,5 ile 2,4 çiftlerini yerleştirip toplam eşitliğinin kalan 6,7,8’i dağıtmasını çözer.',['Fark 8 olan iki 1–9 rakamı yalnız 1 ve 9; ikisi kesişimdedir.','B\A’da çarpımı 8 çift,1 kullanılamadığından 2,4; A\B’de toplam 8 çift 3,5’tir.'],['A’ya özgü toplam 8, B’ye özgü 6; eşit toplamlar için B bölgesine A’dan 2 fazla eklenmeli.','Kalan 6,7,8’den 6 A’ya,8 B’ye,7 ortak bölgeye gider. Kesişim{1,7,9}, toplam 17; B.'],'Küme toplamları eşitse eleman sayıları da eşit sanmak veya ortak 1’i B farkındaki 1 × 8 çiftinde yeniden kullanmak.','Ortak katkıyı yok etme','A ve B toplamları karşılaştırıldığında kesişim aynı katkı yaptığı için silinir; yalnız iki fark bölgesi dengelenir.','A\B toplamı 12, B\A toplamı 12 ise A ve B eleman toplamları nasıldır?',['A büyük','B büyük','Eşit','Boştur','Eleman sayıları eşittir'],2,'Ortak bölge iki tarafa aynı miktarı ekler; fark toplamları eşitse genel toplamlar eşittir.');
M(221,'Olabilir kümesinin üyelik sınırları','Kümelerde işlemler',66,'8’in ortak,10’un yalnız A’da ve 9’un birleşimde bulunması koşullarını olası B tanımlarına ayrı ayrı uygular.',['8 ∈ A∩B bilgisi 8’in B’de bulunmasını gerektirir.','10 ∈ A\B bilgisi 10’un B’de bulunmamasını gerektirir; 9 birleşimde olduğundan gerekirse yalnız A’da olabilir.'],['B bütün çiftler olamaz; çünkü 10’u içerir.','Bir basamaklı doğal sayılar 8’i içerip 10’u içermez; 4’ün katları da aynı gerekli koşulu sağlar. II ve III olabilir; E. 9’un her iki kümede olması istenmez.'],'Birleşimde 9 bulunmasını B’de 9 bulunmalı diye okumak veya I’de 8 uygun diye 10 çelişkisini atlamak.','Varoluşlu küme kurma','Olabilir sorusunda B’nin gerekli üyelikleri sağlaması ve uygun bir A kurulabilmesi yeterlidir; A’nın tamamı belirlenmez.','B, 8’i içermeli,10’u içermemeli. Hangisi uygun olabilir?',['Bütün çiftler','Bütün doğal sayılar','4’ün doğal katları','2’den büyükler','10’dan büyükler'],2,'4’ün katlarında 8 var,10 yoktur.');
M(222,'Üç kümenin adlarını koşullarla eşlemek','Kümelerde fark',67,'4’ün A’da olup C’de olmamasıyla C’yi,5’in B∩C’de olmamasıyla B’yi belirleyip kalan kümeyi A yapar.',['I = {1,2,4}, II = {2,3,5,6}, III = {4,5,6,8}.','4 içermeyen tek küme II olduğundan C = II dir.'],['C, 5’i içerir; 5 ∉ B∩C olması B’nin 5 içermemesini gerektirir. Bu B = I demektir.','Kalan A = III; A, B, C sırası III–I–II, D. 4 ∈ A\C koşulu A’nın 4 içermesini de doğrular.'],'A\C ifadesini C\A gibi okumak veya 5’in kesişimde olmamasını iki kümede de yok sanmak.','Negatif üyelik çıkarımı','Bir kesişimin dışında kalan eleman bir bileşende biliniyorsa öteki bileşende bulunmaması zorunludur.','5 ∈ C ve 5 ∉ B∩C ise hangisi kesindir?',['5 ∈ B','5 ∉ B','B boştur','C boştur','B = C'],1,'B’de de olsaydı kesişimde olurdu; dolayısıyla B’de değildir.');
M(223,'Küp basamaklarda ikili yol seçimi','Saymanın temel ilkesi',70,'Üç basamak inişi ve son minder atlayışındaki ikişer seçimi çarpar; birleşen yolların ayrı hareket dizileri olduğunu korur.',['Her küpten altta ortak ayrıtlı iki komşu basamağa geçilebilir.','Son basamaktaki küpten ortak ayrıtlı iki mavi minder seçilebilir.'],['İlk üç adım 2 × 2 × 2 = 8 farklı iniş yolu verir.','Son adımda her yola 2 minder seçimi eklenir; 8 × 2 = 16 yol, C. Aynı alt kübe varan farklı üst yollar tek sayılmaz.'],'Yalnız alt minder sayısını cevaplamak veya birleşen ara yolları aynı yol kabul edip eksik saymak.','Çarpma ilkesi','Her aşamadaki seçim sayısı önceki kararlarla aynı yapıda kaldığından tüm hareket dizilerinin sayısı çarpımdır.','Üç ardışık adımda 2,3,2 seçim varsa kaç farklı yol vardır?',['7','8','10','12','14'],3,'2 × 3 × 2 = 12.');
M(224,'Üç deneyimli çalışanın aynı ekipte olmaması','Kombinasyon',74,'Sekiz farklı çalışanı etiketli sabah–akşam dört kişilik ekiplere ayırırken üç deneyimlinin aynı ekibe düştüğü iki kötü durumu çıkarır.',['Sabah ekibi seçilince akşam kalanı olur; toplam C(8,4) = 70.','Üç deneyimli sabahsa dördüncü 5 kişiden seçilir; akşamdaysa sabah diğer 5’ten 4 seçilir.'],['İki kötü durum 5 + 5 = 10’dur ve birbirinden ayrıdır.','Geçerli 70 − 10 = 60; D. Sabah–akşam farklı görevler olduğundan sonuç tekrar 2’ye bölünmez.'],'Üç deneyimlinin her ekipte birer kişi olması gibi imkânsız bir eşitlik istemek veyaekip etiketlerini unutarak yarıya bölmek.','Tamamlayıcı sayma','Kısıtı doğrudan dağıtmak yerine iki basit yasak grup çıkarılır; ekipler belirli olduğu için tek ekip seçimi yeterlidir.','6 kişiden sabah 3 kişi seçilecek. Kaç farklı sabah ekibi vardır?',['10','15','20','30','60'],2,'C(6,3) = 20.');
M(225,'Üç okul arasında ikili maç eşleştirmesi','Kombinasyon problemleri',75,'Her okuldan iki öğrencinin kendi okulundan biriyle eşleşememesinde her okul çifti arasında tam bir maç olması gerektiğini kullanır.',['A, B, C okullarının ikişer öğrencisi vardır.','Her okulun iki öğrencisi iki farklı diğer okula gitmelidir; aksi hâlde kalan okul kendi içinde oynamak zorunda kalır.'],['A öğrencilerinden hangisinin B ile oynayacağı 2, hangi B öğrencisiyle oynayacağı 2 şekilde seçilir.','Kalan A’nın hangi C ile oynayacağı 2; son eşleşme zorunlu. 2 × 2 × 2 = 8 eşleştirme, B. Maçların sırası ayrıca sayılmaz.'],'Üç maçın sırasını 3! ile çarpmak veya öğrencileri aynı okuldan oldukları için ayırt etmemek.','Yapısal zorunluluk','Okul başına derece 2 olan üç okul ağı her okul çiftine bir bağ zorlar; sonra yalnız öğrenci atamaları sayılır.','A₁,A₂ ile B₁,B₂ iki okulda kendi okuluyla maç yasaksa iki maç kaç biçimde eşleşir?',['1','2','3','4','6'],1,'A₁ B₁ ile veya B₂ ile oynar; öteki maç belirlenir, iki yol.');
M(226,'Eş kombinasyonların tamamlayıcı seçimleri','Kombinasyon',74,'n kişiden 5 ve 11 seçimlerinin eşitliğini C(n, k) = C(n, n − k) simetrisine bağlar; istenen üçlü seçimi hesaplar.',['Aynı satırda farklı k değerleri eş kombinasyon verirse simetrik eşlerdir.','5 ve 11 farklı olduğu için n = 5 + 11 = 16 olur.'],['Veli nin hesapladığı sayı C(16,3).','16 × 15 × 14/(3 × 2 × 1) = 560; B. Üç kişinin seçimi sıralı görev dağılımı değildir, bu yüzden 3! ile bölünür.'],'C(11,5) hesaplamak veya sınıf mevcudunu 11 almak; 11 seçilecek kişi sayısıdır.','Seçme–seçmeme simetrisi','Bir alt kümeyi seçmek dışarıda kalan tamamlayıcı alt kümeyi seçmekle birebir eşlenir; eş sayı bu simetriyi açığa çıkarır.','C(n,4) = C(n,9) ve 4 ≠ 9 ise n kaçtır?',['9','11','12','13','14'],3,'Tamamlayıcı indeksler toplamı n; 4 + 9 = 13.');
M(227,'Ortak tat içermeyen iki sipariş','Saymanın temel ilkesi',70,'Menüdeki seçeneklerin farklı adlardan oluşmasının yeterli olmadığını, iki siparişin tat kümelerinin ayrık olması gerektiğini uygular.',['Seçenekler V, K, F, VK, VF dir.','Aslı ve Başak farklı kişiler olduğundan sipariş çiftleri sıralıdır.'],['Aslı V seçerse Başak K veya F:2 yol; K seçerse V, F, VF:3; F seçerse V, K, VK:3.','VK için yalnız F:1, VF için yalnız K:1. Toplam 2 + 3 + 3 + 1 + 1 = 10; A. VK ile VF ortak vanilya içerir.'],'Farklı seçenek adlarını otomatik ayrık tatlar sanmak veyakişileri ayırt etmeyerek sonucu ikiye bölmek.','Küme ayrıklığı','Her sipariş bir tat alt kümesidir; uygun ikili, bu alt kümelerin kesişiminin boş olmasıyla tanımlanır.','Seçenekler V, K, F. İki kişi aynı tadı almayacaksa kaç sipariş çifti vardır?',['3','4','5','6','9'],3,'İlk 3, ikinci 2 seçenek; 3 × 2 = 6.');
M(228,'Dört dersin süre toplamı on yedi','Kombinasyon problemleri',75,'Dersleri 5,4,3 saatlik sınıflara ayırıp toplam 17’yi sağlayan tür sayısını belirler, sonra aynı süreli farklı dersleri kombinasyonla seçer.',['5 saatlik 4,4 saatlik 2,3 saatlik 1 ders vardır.','Dört ders için adetler a + b + c = 4 ve 5a + 4b + 3c = 17; çıkarınca a − c = 1.'],['c = 0 olsa a = 1, b = 3 gerekir ama yalnız iki 4 saatlik ders vardır.','c = 1, a = 2, b = 1 mümkün; C(4,2)·C(2,1)·1 = 12 seçim, C. Ders zamanları farklı olduğundan çakışma engeli yoktur.'],'Aynı süreli dersleri özdeş saymak veya 5 + 4 + 4 + 4 toplamı 17 olsa da üç 4 saatlik ders varmış gibi seçmek.','Tür dağılımı ve gerçek seçim','Önce süre türlerinin tamsayı kombinasyonu bulunur; sonra her tür içindeki farklı ders kimlikleri sayılır.','Dört farklı 5 saatlik dersten ikisi kaç şekilde seçilir?',['4','5','6','8','12'],2,'C(4,2) = 6.');
M(229,'Duru bulunan ve bulunmayan üçlüler','Kombinasyon',74,'Duru yu sabitleyince kalan iki kişinin 45 yolla seçilmesini sınıf mevcuduna dönüştürür; istenen grupları Duru dışından seçer.',['Duru bulunan her üçlü, diğer n − 1 kişiden bir ikili seçimine karşılık gelir.','C(n − 1,2) = 45; iki farklı kişi seçimi sırasızdır.'],['(n − 1)(n − 2)/2 = 45; n − 1 = 10, n = 11.','Duru olmayan gruplar diğer 10 kişiden üçlüdür; C(10,3) = 120, E. 45 bu grupların sayısı değil Duru lu gruplardır.'],'Tüm sınıfı 10 kişi sanmak veya istenen sayı için C(11,3) kullanıp Duru yu yeniden dahil etmek.','Sabit üye ile boyut azaltma','Bir eleman grupta zorunlu tutulduğunda seçim boyutu bir azalır; dışlamaksa evren boyutunu bir azaltır.','8 kişiden bir kişi zorunlu üçlülerde kaç grup vardır?',['15','20','21','28','35'],2,'Zorunlu kişi dışındaki 7’den 2 seçilir; C(7,2) = 21.');
M(230,'Bağımsız öncelik kısıtlı beş etkinlik','Permütasyon',72,'Sporun banyodan önce, ödev ve ev işinin filmden önce olması koşullarını iki ayrık öncelik grubunda sayar.',['Beş farklı etkinliğin serbest sırası 5! = 120.','Spor–banyo ikilisinde yarısı uygundur; ödev–ev işi–film üçlüsünde film son olacak biçimlerin payı 1/3’tür.'],['Kısıt grupları farklı etkinlikler içerdiğinden paylar birlikte uygulanır.','120 × 1/2 × 1/3 = 20 sıra; C. Ödevle ev işinin kendi aralarındaki sıra serbesttir.'],'Filmi bütün beş etkinliğin en sonuna zorlamak veya spordan hemen sonra banyo şartı eklemek.','Kısmi sıralama','Önce/sonra bilgisi ardışıklık değildir; ayrık alt grupların göreli düzeni bütün sıraya farklı konumlarda yerleşebilir.','Üç iş A, B, C arasında A, B’den önce olmalı. Kaç sıralama vardır?',['2','3','4','5','6'],1,'3!/2 = 3; A ve B’nin iki göreli sırasından biri uygundur.');
M(231,'İki tarlada eşit sayıda ürün çeşidi','Kombinasyon problemleri',75,'Birinci 4, ikinci 3 seçenekten aynı pozitif adet k seçimini toplar; mısır ve çileğin birlikte seçildiği yasak durumları çıkarır.',['Kısıtsız toplam C(4,1)C(3,1) + C(4,2)C(3,2) + C(4,3)C(3,3) = 34.','Mısır veçilek birlikte seçiliyse k = 1,2,3 için kalan seçim sayıları 1,6,3’tür.'],['Yasak toplam 1 + 6 + 3 = 10.','Geçerli 34 − 10 = 24; B. Her tarlaya en az bir çeşit istendiğinden k = 0 durumu sayılmaz. Ürünler kendi tarlalarına özgüdür.'],'Mısır veyaçilekten herhangi birini tamamen yasaklamak; yalnız ikisinin aynı anda ekilmesi yasaktır.','Tamamlayıcı sayma','Eşit seçim adedi katman katman sayılır; zorunlu iki yasak eleman sabitlenince kalan kombinasyonlar küçülür.','Bir tarlada 3, diğerinde 2’tür var; her birinden bir tür seçilirse kaç seçim vardır?',['3','4','5','6','9'],3,'3 × 2 = 6.');
M(232,'Hatalı tartıda eşit iki sonuç','Olasılık',80,'Gerçek ağırlıkları 80 ve 81 kg olan iki kişinin ortak ölçüm değerlerini bulup her ortak değer için iki bağımsız hatanın çarpımını toplar.',['Ali 79,80,81; Mehmet 80,81,82 ölçülebilir.','Ortak sonuçlar yalnız 80 ve 81; iki ölçümün hata olayları ayrı uygulanır.'],['80 için Ali doğru%50, Mehmet − 1%30; olasılık 0,5 × 0,3 = 0,15.','81 için Ali + 1%20, Mehmet doğru%50; 0,2 × 0,5 = 0,10. Toplam%25; D. İki ortak sonuç ayrık olaydır.'],'Her ikisinin doğru tartılmasını eşit sonuç sanmak; doğru ağırlıkları zaten farklıdır.','Ayrık yolları toplama','Tek eşitlik olayı farklı ölçüm çiftleriyle gerçekleşebilir; her çiftin olasılığı çarpılır, ayrık çiftler toplanır.','A’nın ölçümü 10 veya 11, B’nin ölçümü 11 veya 12’yi eşit olasılıkla ölçüyor. Eşit sonuç olasılığı kaçtır?',['1/4','1/3','1/2','2/3','3/4'],0,'Yalnız A 11 ve B 11 ortak; 1/2 × 1/2 = 1/4.');
M(233,'Kart toplamında tekrar eden değer','Olasılık',80,'Dört farklı karttan ikili seçimin altı eş olasılıklı sonucunu yazar; 1/3 oranının iki uygun çift gerektirdiğini kullanır.',['C(4,2) = 6 ikili vardır.','Toplamlar 14,16,18,18,20,22’dir; 18 iki farklı çiftten gelir.'],['6 + 12 = 18 ve 8 + 10 = 18; diğer toplamlar birer kez oluşur.','1/3 = 2/6 koşulunu yalnız 18 sağlar. Yiğit 18 yaşındadır; C. Aynı toplam çıkan çiftler farklı seçimler olarak kalır.'],'Farklı toplam değerlerini eş olasılıklı beş sonuç saymak; eş olasılıklı olan kart ikilileridir.','Örnek uzay tanımı','Bir sonuca birden çok eş olasılıklı temel seçim karşılık gelebilir; olasılık değerlerin sayısıyla değil ön görüntüleriyle hesaplanır.','2,4,6,8 kartlarından iki seçince toplam 10 kaç çiftle oluşur?',['1','2','3','4','5'],1,'2 + 8 ve 4 + 6; iki çift.');
M(234,'Her satır ve sütundan bir sayı seçmek','Olasılık',80,'3 × 3 tuşlarda satır ve sütun kısıtının 6 permütasyon bıraktığını görür; tek sayılar için orta satırdaki 5’i zorunlu seçer.',['Her satırdan ve sütundan bir seçim, üç sütunun 3! eşleştirmesidir.','Orta satır 4,5,6 içinde tek yalnız 5’tir; orta sütun kullanılmış olur.'],['Üst satırda 1 veya 3 seçilebilir; alt satırda kalan sütunun 7 veya 9’u zorunludur.','İki uygun seçim/altı toplam = 1/3; B. Beş tek rakamdan herhangi üçlü seçmek satır–sütun şartını bozabilir.'],'Bağımsız üç seçim gibi(5/9)³ hesaplamak veya bütün C(9,3) üçlülerini eş olasılıklı geçerli uzay saymak.','Koşullu örnek uzay','Önceden konmuş satır ve sütun kısıtı örnek uzayı daraltır; olasılık yalnız bu alt uzay üzerinde hesaplanır.','2 × 2 tabloda her satır ve sütundan bir kare kaç şekilde seçilir?',['1','2','3','4','6'],1,'İki köşegen seçimi vardır.');
M(235,'Araba içeren dört görüntü karesi','Olasılık',80,'3 × 3 görselde arabanın orta ve alt satırların sağ iki sütununa yayıldığını okuyup rastgele dört kare seçimini tek doğru kümeyle karşılaştırır.',['Dokuz kareden dört farklı kare seçimi C(9,4) = 126’dır.','Araba parçası bulunanlar orta–sağ, orta–orta, alt–orta, alt–sağ olmak üzere dört belirli karedir.'],['Giriş için bu dört karenin tamamı seçilmelidir; başka bir dörtlü eksik veya fazla yanlış kare içerir.','Uygun 1 seçim/126 toplam = 1/126; E. Seçim sırası onaylanan kare kümesini değiştirmez.'],'Arabada en çok parça bulunan iki kareyi yeterli saymak veya dört karenin seçilme sırasını ayrıca çarpmak.','Tek hedef alt küme','Doğru görsel etiketleme belirli bir alt kümeyi ister; aynı büyüklükte rastgele seçimler arasında tek uygun küme vardır.','8 kareden doğru 3 kareyi eksiksiz seçme olasılığı kaçtır?',['1/24','1/35','1/56','1/64','1/120'],2,'C(8,3) = 56 farklı üçlüden yalnız biri doğrudur.');
M(236,'Bozuk klavyede giriş ve çıkan harfler','Olasılık',80,'T, T, Y basışlarında ekranda T, Y, T oluşmasını her basışın kendi tuş hata olasılığıyla sırayla eşler.',['İlk T basışında T çıkması 3/4.','İkinci T’de Y çıkması 1/4, son Y’de T çıkması 1/3’tür.'],['İstenen belirli sıra için olasılıklar çarpılır.','(3/4) × (1/4) × (1/3) = 1/16; B. Son basışta Y tuşuna basılması ekranda Y isteniyor anlamına gelmez.'],'Yazılması istenen T kelimesini basılan tuşla karıştırmak veya aynı T tuşuna iki kez basılınca çıktının aynı olacağını varsaymak.','Bağımsız sıralı olaylar','Her konumdaki koşul ayrı olaydır; bir tek çıktı dizisi istendiğinden olası permütasyonlarla ayrıca çarpılmaz.','İki bağımsız basışta doğru harf olasılığı 3/4 ise ikisinin de doğru olasılığı kaçtır?',['1/4','3/8','1/2','9/16','3/4'],3,'3/4 × 3/4 = 9/16.');
M(237,'Ocakta bir orta ve küçük göz','Olasılık',80,'Dört düğmenin dört farklı bölmeye birebir bağlılığından iki düğme seçimini iki bölme seçimiyle eşler; iki orta gözün farklı olduğunu korur.',['Toplam C(4,2) = 6 ikili düğme seçimi vardır.','Uygun ikili küçük göz düğmesi ve iki orta gözden birinin düğmesidir.'],['Küçük 1, orta 2 seçenek verdiğinden uygun 2 ikili.','Olasılık 2/6 = 1/3; B. Büyük gözle küçük göz ikilisi veyaiki orta göz istenen olay değildir. Tuş eşleşmesinin bilinmemesi bütün ikilileri simetrik kılar.'],'Orta gözleri aynı tür diye tek fiziksel göz saymak veya sıra önemliymiş gibi yalnız payı ikiyle çarpmak.','Birebir eşleme','Düğme–bölme ilişkisi permütasyon olsa da rastgele iki düğme tüm iki bölmeli alt kümeleri eş olasılıklı verir.','5 düğmeden biri küçük, ikisi orta. İki düğmeyle küçük ve bir orta seçilme olasılığı nedir?',['1/10','1/5','2/5','1/2','3/5'],1,'Uygun 2, toplam C(5,2) = 10; 2/10 = 1/5.');
M(238,'Altı paketin 1–2–3 kişi gruplarına dağıtımı','Olasılık',80,'Herkesin beklediği adetleri aldığı koşul altında paket kimliklerinin rastgele paylaşımını sayar; yalnız bir paylaşım tüm alıcıları doğru verir.',['Erman a1 paket C(6,1), Görkem e kalanlardan 2 paket C(5,2) seçilir.','Kerem kalan 3’ü alır; toplam 6 × 10 = 60 eş olasılıklı paylaşım vardır.'],['Her paketin gerçek alıcısı belirli olduğundan doğru paylaşım tektir.','Olasılık 1/60; B. Her kişinin doğru paket adedini almış olması paketlerin doğru kişilere gittiğini garanti etmez.'],'Altı paketi özdeş saymak veya her kişiye aynı 2 paket dağıtmak; adet koşulu 1,2,3’tür.','Etiketli gruplara dağıtım','Gruplar farklı kişilerle etiketlidir; 1 ve 2 paketli grupların seçiminden sonra kalan grup zorunlu belirlenir.','4 farklı paket 1 ve 3 adet alan iki kişiye dağıtılıyor. Doğru dağıtım olasılığı nedir?',['1/2','1/3','1/4','1/6','1/12'],2,'Tek paket alanın 4 olası seçimi var; yalnız biri kendi paketi,1/4.');
M(239,'İki arkadaştan en az birine hediye','Olasılık',80,'Altı arkadaşın ikisine hediye verilmesinde Doğa ve Duru dan hiçbirinin seçilmediği tamamlayıcı olayı çıkarır.',['Toplam C(6,2) = 15 ikili.','Hiçbiri seçilmiyorsa diğer 4 arkadaştan 2 kişi, C(4,2) = 6 ikili vardır.'],['En az bir uygun ikili sayısı 15 − 6 = 9.','Olasılık 9/15 = 3/5; B. İkisine birden hediye verilen durum da en az bir olayının içindedir.'],'Tam bir kişiye hediye verilmesiyle en az bir kişiye verilmesini karıştırmak veya iki kişinin olasılıklarını ortak durumu düzeltmeden toplamak.','Tamamlayıcı olay','En az bir koşulu, birden çok uygun alt durumu saymak yerine hiçbirini sayıp 1’den çıkararak kolaylaşır.','5 kişiden 2 seçiliyor, biri Ece. Ece nin seçilme olasılığı kaçtır?',['1/5','2/5','1/2','3/5','4/5'],1,'Ece ile diğer 4 kişiden biri:4/C(5,2) = 4/10 = 2/5.');
M(240,'Defolu ikiliden defolu sayısına','Olasılık',80,'25 halıdan iki defolunun%1 olmasını toplam 300 ikili içinde 3 uygun çift olarak yorumlayıp defolu sayısını belirler.',['Toplam C(25,2) = 300 ikili vardır.','Defolu d ise C(d,2)/300 = 0,01; C(d,2) = 3 olur.'],['d(d − 1)/2 = 3; pozitif tamsayı d = 3. Sağlam 22 halı vardır.','İki sağlam olasılığı C(22,2)/300 = 231/300 = 0,77;%77, A. Seçimler geri koymadan yapıldığı için oranlar değişir.'],'Sağlam oranını%99 sanmak;%1 iki defolu olayıdır, tek halının defolu olasılığı değildir.','Olaydan nüfus çıkarma','Çift seçimin olasılığı uygun çift sayısını verir; önce bu ters problem çözülür, sonra başka olay hesaplanır.','10 üründe 2 defolu varsa iki sağlam seçilme olasılığı nedir?',['14/45','22/45','28/45','32/45','4/5'],2,'C(8,2)/C(10,2) = 28/45.');
window. EXAM_ANALYSES={...(window. EXAM_ANALYSES||{}),...rows};
})();
